    ["src/games/features/noobpiece/wanderinggacha.lua"] = [[
local Players=game:GetService("Players")
local Workspace=game:GetService("Workspace")

local WanderingGacha={}
WanderingGacha.__index=WanderingGacha

local MOVEMENT_OWNER="WanderingGacha"

function WanderingGacha.new(movement)
    return setmetatable({
        Player=Players.LocalPlayer,
        Movement=movement,
        Offset=4
    },WanderingGacha)
end

function WanderingGacha:_root(model)
    if not model then return nil end

    if model:IsA("BasePart") then
        return model
    end

    if model:IsA("Model") then
        return model.PrimaryPart
            or model:FindFirstChild("HumanoidRootPart")
            or model:FindFirstChildWhichIsA("BasePart",true)
    end

    return nil
end

function WanderingGacha:GetNpc()
    local folder=Workspace:FindFirstChild("WanderingGacha")
    if not folder then return nil end
    return folder:FindFirstChild("WanderingGacha")
end

function WanderingGacha:Teleport()
    local npc=self:GetNpc()
    local root=self:_root(npc)
    if not root or not self.Movement then
        return false
    end

    local position=root.Position-root.CFrame.LookVector*self.Offset
    local goal=CFrame.lookAt(
        position,
        Vector3.new(root.Position.X,position.Y,root.Position.Z)
    )

    return self.Movement:FlyTo(goal,nil,MOVEMENT_OWNER)
end

function WanderingGacha:Destroy()
end

return WanderingGacha

]],
    ["src/games/features/restauranttycoon3/autofarm-friends.lua"] = [[
local Players = game:GetService("Players")
local localPlayer = Players.LocalPlayer

-- Humanised timing: vary periodic waits so the automation loop is not perfectly periodic.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local AutoFarmFriendsModule = {}
AutoFarmFriendsModule.Enabled = false

local activeInteractions = {}
local farmThread = nil

local friendList = {}
local lastFriendUpdate = 0

local function updateFriendsList()
    local currentTime = tick()
    if currentTime - lastFriendUpdate < 30 then return end

    table.clear(friendList)
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= localPlayer then
            pcall(function()
                if localPlayer:IsFriendsWith(player.UserId) then
                    friendList[player.Name] = true
                end
            end)
        end
    end
    lastFriendUpdate = currentTime
end

local function getFriendTycoons()
    local tycoonsFolder = workspace:FindFirstChild("Tycoons")
    if not tycoonsFolder then return {} end

    local friendTycoons = {}

    for _, tycoon in ipairs(tycoonsFolder:GetChildren()) do
        local playerValue = tycoon:FindFirstChild("Player")
        if playerValue then
            local ownerName = nil
            if playerValue:IsA("ObjectValue") and playerValue.Value then
                ownerName = playerValue.Value.Name
            elseif playerValue:IsA("StringValue") and playerValue.Value ~= "" then
                ownerName = playerValue.Value
            end

            if ownerName and friendList[ownerName] then
                table.insert(friendTycoons, tycoon)
            end
        end
    end

    return friendTycoons
end

local function instantRemoteTrigger(prompt)
    if not AutoFarmFriendsModule.Enabled then return end
    if activeInteractions[prompt] then return end
    if prompt.ActionText == "Cook" or prompt.ObjectText == "Cook" or prompt.Name == "Cook" then return end

    activeInteractions[prompt] = true

    task.spawn(function()
        pcall(function()
            if fireproximityprompt then
                fireproximityprompt(prompt)
            else
                prompt:InputHoldBegin()
                task.wait(prompt.HoldDuration + 0.01)
                prompt:InputHoldEnd()
            end
        end)

        task.wait(0.05)
        activeInteractions[prompt] = nil
    end)
end

function AutoFarmFriendsModule.Start()
    if AutoFarmFriendsModule.Enabled then return end
    AutoFarmFriendsModule.Enabled = true
    updateFriendsList()

    farmThread = task.spawn(function()
        while AutoFarmFriendsModule.Enabled do
            updateFriendsList()

            pcall(function()
                local friendTycoons = getFriendTycoons()
                for _, tycoon in ipairs(friendTycoons) do
                    if not AutoFarmFriendsModule.Enabled then break end
                    local tycoonDescendants = tycoon:GetDescendants()
                    for i = 1, #tycoonDescendants do
                        if not AutoFarmFriendsModule.Enabled then break end
                        local desc = tycoonDescendants[i]
                        if desc:IsA("ProximityPrompt") and desc.Name == "CustomerInteractPrompt" and desc.Enabled then
                            instantRemoteTrigger(desc)
                        end
                    end
                end
            end)

            local tempFolder = workspace:FindFirstChild("Temp")
            if tempFolder then
                pcall(function()
                    local tempDescendants = tempFolder:GetDescendants()
                    for i = 1, #tempDescendants do
                        if not AutoFarmFriendsModule.Enabled then break end
                        local desc = tempDescendants[i]
                        if desc:IsA("ProximityPrompt") and desc.Enabled then
                            instantRemoteTrigger(desc)
                        end
                    end
                end)
            end

            jitter(0.1)
        end
    end)
    print("[Auto Farm Friends] Ativado com Sucesso!")
end

function AutoFarmFriendsModule.Stop()
    if not AutoFarmFriendsModule.Enabled then return end
    AutoFarmFriendsModule.Enabled = false
    table.clear(activeInteractions)

    local thread = farmThread
    farmThread = nil
    if thread then
        pcall(function()
            if type(task) == "table" and type(task.cancel) == "function" then
                task.cancel(thread)
            elseif type(coroutine.close) == "function" then
                coroutine.close(thread)
            end
        end)
    end

    print("[Auto Farm Friends] Desativado!")
end

function AutoFarmFriendsModule.Toggle(state)
    if state then
        AutoFarmFriendsModule.Start()
    else
        AutoFarmFriendsModule.Stop()
    end
end

AutoFarmFriendsModule.Set = AutoFarmFriendsModule.Toggle

return AutoFarmFriendsModule
]],
    ["src/games/features/restauranttycoon3/autofarm.lua"] = [[
local cl_game = game
local cl_workspace = workspace
local cl_players = cl_game:GetService("Players")
local cl_localplayer = cl_players.LocalPlayer

local cl_findfirstchild = cl_game.FindFirstChild
local cl_getdescendants = cl_game.GetDescendants
local cl_getchildren = cl_game.GetChildren
local cl_isa = cl_game.IsA

local cl_task = task
local cl_spawn = cl_task.spawn
local cl_wait = cl_task.wait
local cl_cancel = cl_task.cancel

local cl_pcall = pcall
local cl_clear = table.clear
local cl_vector3 = Vector3.new

local cl_fireprompt = fireproximityprompt or nil
local cl_fireclick = fireclickdetector or nil
local cl_vu = cl_game:GetService("VirtualUser")

local AutoFarmModule = {}
AutoFarmModule.Enabled = false

local activeInteractions = {}
local farmThread = nil

local function getMyTycoon()
    local tycoonsFolder = cl_findfirstchild(cl_workspace, "Tycoons")
    if not tycoonsFolder then return nil end

    local children = cl_getchildren(tycoonsFolder)
    for i = 1, #children do
        local tycoon = children[i]
        local playerValue = cl_findfirstchild(tycoon, "Player")
        if playerValue then
            if cl_isa(playerValue, "ObjectValue") and playerValue.Value == cl_localplayer then
                return tycoon
            end

            if cl_isa(playerValue, "StringValue") and tostring(playerValue.Value) == cl_localplayer.Name then
                return tycoon
            end
        end
    end

    return nil
end

local function interactWithModel(model)
    if not AutoFarmModule.Enabled or activeInteractions[model] then return end
    activeInteractions[model] = true

    cl_spawn(function()
        cl_pcall(function()
            local character = cl_localplayer.Character
            local rootPart = character and cl_findfirstchild(character, "HumanoidRootPart")
            local targetPart = model.PrimaryPart or cl_findfirstchild(model, "Part", true) or cl_findfirstchild(model, "Base", true) or cl_findfirstchild(model, "MeshPart", true)

            if rootPart and targetPart and cl_isa(targetPart, "BasePart") then
                local originalCFrame = rootPart.CFrame
                rootPart.CFrame = targetPart.CFrame * CFrame.new(cl_vector3(0, 1.5, 0))
                cl_wait(0.012)

                local detector = cl_findfirstchild(model, "ClickDetector", true) or cl_findfirstchild(targetPart, "ClickDetector")
                if detector and cl_fireclick then
                    cl_fireclick(detector)
                else
                    cl_vu:ClickButton1(cl_vector3(0, 0, 0), cl_workspace.CurrentCamera.CFrame)
                end

                cl_wait(0.01)
                rootPart.CFrame = originalCFrame
            end
        end)
        cl_wait(0.04)
        activeInteractions[model] = nil
    end)
end

local function triggerPrompt(prompt)
    if not AutoFarmModule.Enabled or activeInteractions[prompt] then return end

    local name = prompt.Name
    local action = prompt.ActionText
    local object = prompt.ObjectText

    if action == "Cook" or object == "Cook" or name == "Cook" then return end

    activeInteractions[prompt] = true

    cl_spawn(function()
        cl_pcall(function()
            local character = cl_localplayer.Character
            local rootPart = character and cl_findfirstchild(character, "HumanoidRootPart")
            local parentPart = prompt.Parent

            local originalCFrame
            local targetPart = nil

            if parentPart then
                if cl_isa(parentPart, "BasePart") then
                    targetPart = parentPart
                elseif cl_isa(parentPart, "Model") then
                    targetPart = cl_findfirstchild(parentPart, "HumanoidRootPart") or parentPart.PrimaryPart or cl_findfirstchild(parentPart, "Part", true)
                end
            end

            if rootPart and targetPart then
                originalCFrame = rootPart.CFrame
                rootPart.CFrame = targetPart.CFrame * CFrame.new(cl_vector3(0, 1.5, 0))
                cl_wait(0.012)
            end

            if cl_fireprompt then
                cl_fireprompt(prompt)
            else
                prompt:InputHoldBegin()
                cl_wait(prompt.HoldDuration + 0.01)
                prompt:InputHoldEnd()
            end

            if rootPart and originalCFrame then
                rootPart.CFrame = originalCFrame
            end
        end)

        cl_wait(0.04)
        activeInteractions[prompt] = nil
    end)
end

function AutoFarmModule.Start()
    if AutoFarmModule.Enabled then return end
    AutoFarmModule.Enabled = true

    farmThread = cl_spawn(function()
        local myTycoon

        while AutoFarmModule.Enabled do
            if not myTycoon or not myTycoon.Parent then
                myTycoon = getMyTycoon()
            end

            if myTycoon then
                cl_pcall(function()
                    local items = cl_findfirstchild(myTycoon, "Items")
                    local surface = items and cl_findfirstchild(items, "Surface")

                    if surface then
                        local surfaceDescendants = cl_getdescendants(surface)
                        for i = 1, #surfaceDescendants do
                            local desc = surfaceDescendants[i]
                            if not AutoFarmModule.Enabled then break end

                            if cl_isa(desc, "Model") and (desc.Name == "Bill" or desc.Name == "Trash") then
                                interactWithModel(desc)
                            end
                        end
                    end

                    local tycoonDescendants = cl_getdescendants(myTycoon)
                    for i = 1, #tycoonDescendants do
                        local desc = tycoonDescendants[i]
                        if not AutoFarmModule.Enabled then break end

                        if cl_isa(desc, "ProximityPrompt") and desc.Name == "CustomerInteractPrompt" and desc.Enabled then
                            triggerPrompt(desc)
                        end
                    end
                end)
            end

            cl_wait(0.08)
        end
    end)
end

function AutoFarmModule.Stop()
    if not AutoFarmModule.Enabled then return end
    AutoFarmModule.Enabled = false
    cl_clear(activeInteractions)

    if farmThread then
        cl_pcall(function()
            cl_cancel(farmThread)
        end)
        farmThread = nil
    end
end

function AutoFarmModule.Toggle(state)
    if state then
        AutoFarmModule.Start()
    else
        AutoFarmModule.Stop()
    end
end

AutoFarmModule.Set = AutoFarmModule.Toggle

return AutoFarmModule

]],
    ["src/games/features/restauranttycoon3/drops.lua"] = [[
local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")
local localPlayer = Players.LocalPlayer

local AutoDropModule = {}
AutoDropModule.Enabled = false

-- Humanised timing: vary the poll interval so the scan loop is not perfectly periodic.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local dropThread = nil
local dropConnection = nil
local boundFolder = nil
local generation = 0
local activeDrops = {}

local function processDrop(drop)
    if not AutoDropModule.Enabled or activeDrops[drop] then return end

    local character = localPlayer.Character
    local hrp = character and character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local token = generation
    activeDrops[drop] = token
    task.spawn(function()
        if not AutoDropModule.Enabled or token ~= generation or not drop.Parent or localPlayer.Character ~= hrp.Parent then
            if activeDrops[drop] == token then activeDrops[drop] = nil end
            return
        end
        pcall(function()
            local touchInterest = drop:FindFirstChildOfClass("TouchInterest") or drop:FindFirstChild("TouchInterest")
            if touchInterest and firetouchinterest then
                firetouchinterest(hrp, drop, 0)
                task.wait(0.01)
                firetouchinterest(hrp, drop, 1)
            elseif drop:IsA("Model") then
                drop:PivotTo(hrp.CFrame)
            elseif drop:IsA("BasePart") then
                drop.CFrame = hrp.CFrame
            end
        end)

        task.wait(0.1)
        if activeDrops[drop] == token then activeDrops[drop] = nil end
    end)
end

function AutoDropModule.Start()
    if AutoDropModule.Enabled then return end
    AutoDropModule.Enabled = true
    generation += 1

    dropThread = task.spawn(function()
        while AutoDropModule.Enabled do
            local dropFolder = Workspace:FindFirstChild("DropFolder")

            if dropFolder ~= boundFolder then
                if dropConnection then dropConnection:Disconnect(); dropConnection = nil end
                boundFolder = dropFolder
            end
            if dropFolder then
                if not dropConnection then
                    dropConnection = dropFolder.ChildAdded:Connect(function(child)
                        if AutoDropModule.Enabled then
                            processDrop(child)
                        end
                    end)
                end

                pcall(function()
                    for _, drop in ipairs(dropFolder:GetChildren()) do
                        if not AutoDropModule.Enabled then break end
                        processDrop(drop)
                    end
                end)
            end

            jitter(0.15)
        end
    end)
end

function AutoDropModule.Stop()
    if not AutoDropModule.Enabled then return end
    AutoDropModule.Enabled = false
    generation += 1
    boundFolder = nil
    table.clear(activeDrops)

    if dropConnection then
        pcall(function()
            dropConnection:Disconnect()
        end)
        dropConnection = nil
    end

    if dropThread then
        pcall(function()
            task.cancel(dropThread)
        end)
        dropThread = nil
    end
end

function AutoDropModule.Toggle(state)
    if state then
        AutoDropModule.Start()
    else
        AutoDropModule.Stop()
    end
end

AutoDropModule.Set = AutoDropModule.Toggle

return AutoDropModule


]],
    ["src/games/features/restauranttycoon3/instant-cook.lua"] = [[
local cl_game = game
local cl_workspace = workspace
local cl_players = cl_game:GetService("Players")
local cl_localplayer = cl_players.LocalPlayer

local cl_findfirstchild = cl_game.FindFirstChild
local cl_getdescendants = cl_game.GetDescendants
local cl_getchildren = cl_game.GetChildren
local cl_isa = cl_game.IsA

local cl_task = task
local cl_spawn = cl_task.spawn
local cl_wait = cl_task.wait
local cl_cancel = cl_task.cancel

local cl_pcall = pcall
local cl_clear = table.clear
local cl_vector3 = Vector3.new

local cl_fireprompt = fireproximityprompt or nil

local cl_replicatedstorage = cl_game:GetService("ReplicatedStorage")
local cl_runservice = cl_game:GetService("RunService")

local eventsFolder = cl_findfirstchild(cl_replicatedstorage, "Events")
local cookFolder = eventsFolder and cl_findfirstchild(eventsFolder, "Cook")
local cookInputRemote = cookFolder and cl_findfirstchild(cookFolder, "CookInputRequested")
local cookUpdatedEvent = cookFolder and cl_findfirstchild(cookFolder, "CookUpdated")

local CookModule = {
    Enabled = false,
    FixedPosition = nil,
    IsCooking = false
}

local connections = {}
local loopThreads = {}

local function getMyTycoon()
    local tycoonsFolder = cl_findfirstchild(cl_workspace, "Tycoons")
    if not tycoonsFolder then return nil end

    local children = cl_getchildren(tycoonsFolder)
    for i = 1, #children do
        local tycoon = children[i]
        local playerValue = cl_findfirstchild(tycoon, "Player")
        if playerValue then
            if cl_isa(playerValue, "ObjectValue") and playerValue.Value == cl_localplayer then
                return tycoon
            end

            if cl_isa(playerValue, "StringValue") and tostring(playerValue.Value) == cl_localplayer.Name then
                return tycoon
            end
        end
    end

    return nil
end

local function belongsToMyTycoon(instance, tycoon)
    if not instance or not tycoon then return false end
    return instance == tycoon or instance:IsDescendantOf(tycoon)
end

local function unanchorCharacter()
    local character = cl_localplayer.Character
    if not character then return end

    local descendants = cl_getdescendants(character)
    for i = 1, #descendants do
        local part = descendants[i]
        if cl_isa(part, "BasePart") and part.Anchored then
            part.Anchored = false
        end
    end
end

local function instantProcess(equipment, stationType, myTycoon)
    if not CookModule.Enabled or not equipment or not stationType or not cookInputRemote then return end
    if not belongsToMyTycoon(equipment, myTycoon) then return end

    CookModule.IsCooking = true
    unanchorCharacter()

    local character = cl_localplayer.Character
    local hrp = character and cl_findfirstchild(character, "HumanoidRootPart")
    if hrp then
        CookModule.FixedPosition = hrp.CFrame
    end

    cl_spawn(function()
        cl_pcall(function()
            cookInputRemote:FireServer("Interact", equipment, stationType)
            cl_wait(0.02)
            cookInputRemote:FireServer("CompleteTask", equipment, stationType, false)
        end)
        cl_wait(0.03)
        unanchorCharacter()
        CookModule.IsCooking = false
        CookModule.FixedPosition = nil
    end)
end

function CookModule.Start()
    if CookModule.Enabled then return end
    CookModule.Enabled = true

    connections[#connections + 1] = cl_runservice.Heartbeat:Connect(function()
        if not CookModule.Enabled then return end

        unanchorCharacter()

        if not CookModule.IsCooking or not CookModule.FixedPosition then return end

        local character = cl_localplayer.Character
        if not character then return end

        local root = cl_findfirstchild(character, "HumanoidRootPart")
        if root then
            if (root.Position - CookModule.FixedPosition.Position).Magnitude > 0.05 then
                root.CFrame = CookModule.FixedPosition
            end
            root.AssemblyLinearVelocity = cl_vector3(0, 0, 0)
            root.AssemblyAngularVelocity = cl_vector3(0, 0, 0)
        end

        local humanoid = cl_findfirstchild(character, "Humanoid")
        if humanoid and humanoid.PlatformStand then
            humanoid.PlatformStand = false
        end
    end)

    local myTycoon = getMyTycoon()

    if cookUpdatedEvent then
        connections[#connections + 1] = cookUpdatedEvent.OnClientEvent:Connect(function(actionType, p1, p2, p3, p4)
            if not CookModule.Enabled then return end

            local currentTycoon = myTycoon
            if not currentTycoon or not currentTycoon.Parent then
                currentTycoon = getMyTycoon()
                myTycoon = currentTycoon
            end

            if actionType == "DirectToEquipment" and typeof(p1) == "Instance" then
                instantProcess(p1, p2, currentTycoon)
            elseif actionType == "UpdateInteraction" and typeof(p2) == "Instance" and p4 == true then
                instantProcess(p2, p3, currentTycoon)
            end
        end)
    end

    loopThreads[#loopThreads + 1] = cl_spawn(function()
        while CookModule.Enabled do
            if not myTycoon or not myTycoon.Parent then
                myTycoon = getMyTycoon()
            end

            if myTycoon and not CookModule.IsCooking then
                cl_pcall(function()
                    local descendants = cl_getdescendants(myTycoon)
                    for i = 1, #descendants do
                        if not CookModule.Enabled or CookModule.IsCooking then break end

                        local desc = descendants[i]
                        if cl_isa(desc, "ProximityPrompt") and desc.Enabled and (desc.ActionText == "Cook" or desc.ObjectText == "Cook" or desc.Name == "Cook") then
                            unanchorCharacter()

                            local character = cl_localplayer.Character
                            local hrp = character and cl_findfirstchild(character, "HumanoidRootPart")
                            if hrp then
                                CookModule.FixedPosition = hrp.CFrame
                            end

                            CookModule.IsCooking = true

                            cl_pcall(function()
                                if cl_fireprompt then
                                    cl_fireprompt(desc)
                                else
                                    desc:InputHoldBegin()
                                    cl_wait(desc.HoldDuration + 0.005)
                                    desc:InputHoldEnd()
                                end
                            end)

                            cl_wait(0.05)
                            unanchorCharacter()
                            CookModule.IsCooking = false
                            CookModule.FixedPosition = nil
                        end
                    end
                end)
            end

            cl_wait(0.1)
        end
    end)
end

function CookModule.Stop()
    if not CookModule.Enabled then return end
    CookModule.Enabled = false
    CookModule.IsCooking = false

    for i = 1, #connections do
        local connection = connections[i]
        if connection then
            connection:Disconnect()
        end
    end

    for i = 1, #loopThreads do
        local thread = loopThreads[i]
        if thread then
            cl_cancel(thread)
        end
    end

    cl_clear(connections)
    cl_clear(loopThreads)
    CookModule.FixedPosition = nil
    unanchorCharacter()
end

function CookModule.Toggle(state)
    if state then
        CookModule.Start()
    else
        CookModule.Stop()
    end
end

CookModule.Set = CookModule.Toggle

return CookModule

]],
    ["src/games/features/stealanexu/autosteal.lua"] = [[
-- Auto Steal Exu -- rouba os Exu por teleporte instantaneo, com noclip e o
-- personagem parado no ar (ancorado) pra nao bugar dentro do cenario.
--
-- O JOGO (o que este modulo assume):
--
--   * workspace.Runtime -- os MODELOS dos Exu, um por Exu no servidor. O prompt
--     vive em cada modelo: Model.Root.ProximityPrompt. E a VARREDURA e' aqui:
--     percorre os filhos do Runtime e rouba um por um -- e' assim que se pega
--     VARIOS Exus (os Nests podem apontar pro mesmo Exu por proximidade).
--   * workspace.Map.Terreiros.TerreiroN -- as fases, N = 1..9, com .Nests
--     Nest1..8. Sao so referencia visual do jogo; o roubo nao depende delas.
--   * workspace.Map.Pens.PenX -- as bases, uma por jogador. Cada base tem o
--     atributo "Owner" (o UserId do dono) e um BadgeAnchor (o ponto onde o
--     jogador "guarda" o Exu). A NUMERACAO Pen1/Pen2 muda por servidor, entao a
--     base certa so se acha pelo atributo Owner == LocalPlayer.UserId.
--
-- O CICLO de cada roubo (pedido do usuario):
--   1) teleporta pro Exu (Root do modelo do Runtime);
--   2) espera o prompt assentar (no alcance);
--   3) dispara o prompt (HoldDuration=0 + InputHoldBegin/End); teleporta pra base;
--   4) espera VALIDATE_WAIT na base (o jogo confirmar o guardar);
--   5) proximo Exu.
--
-- Enquanto roda, o personagem fica ANCORADO no ar e SEM colisao (noclip): sem
-- gravidade, sem colisao, sem fisica brigando com o teleporte. Ao parar, tudo e
-- restaurado (colisao e ancoragem originais).

local game = game
local task = task
local type = type
local pcall = pcall
local tostring = tostring
local math = math
local table = table
local select = select

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")
local LocalPlayer = Players.LocalPlayer

local AutoSteal = {}
AutoSteal.__index = AutoSteal

-- TEMPOS (calibraveis). O usuario reclamou que "nao pega os exu, acho que ta mto
-- rapido", entao tudo aqui esta folgado de proposito -- da pra ir apertando
-- conforme o jogo responder.
--
-- Auto Steal Exu (toggle):
--   VALIDATE_WAIT   -- quanto esperar na base depois de roubar (o jogo confirmar
--                      o guardar) antes de ir pro proximo Exu.
--   SETTLE_WAIT     -- quanto esperar parado em cima do Exu depois do teleporte,
--                      pro prompt assentar antes de segurar (era o task.wait(0.1)
--                      do script de referencia; subiu pra 0.3).
--   POST_HOLD_WAIT  -- quanto ficar EM CIMA do Exu depois do InputHoldEnd, pro
--                      servidor creditar o roubo antes de a gente sair de perto.
local VALIDATE_WAIT = 1.5
local SETTLE_WAIT = 0.3
local POST_HOLD_WAIT = 0.15

-- Steal All (botao): mesma logica, so que mais apertada que o toggle (o usuario
-- quer o botao "um pouco mais forte e rapido"). Ainda assim, folgada o bastante
-- pra o servidor processar.
local ALL_VALIDATE_WAIT = 0.8
local ALL_SETTLE_WAIT = 0.3
local ALL_POST_HOLD_WAIT = 0.15
-- Um respiro entre um Exu e o proximo, pra nao metralhar o servidor.
local ALL_STEP_GAP = 0.15

-- --- Debug ----------------------------------------------------------------
-- Log de diagnostico por etapa. Vai pro console (print) e fica guardado em
-- self.DebugLog pra inspecao. Desligavel com AutoSteal.DebugEnabled = false.
AutoSteal.DebugEnabled = true
local DEBUG_TAG = "[StealAnExu]"

-- O env do hub (getgenv/_G), pra publicar o log no Debug do painel quando existir.
local env = type(getgenv) == "function" and getgenv() or _G

local function debugLog(self, ...)
    local parts = {}
    for index = 1, select("#", ...) do
        parts[#parts + 1] = tostring(select(index, ...))
    end
    local message = DEBUG_TAG .. " " .. table.concat(parts, " ")
    self.DebugLog = self.DebugLog or {}
    self.DebugLog[#self.DebugLog + 1] = message
    -- Mantem a lista curta (ultimas 200 linhas).
    if #self.DebugLog > 200 then table.remove(self.DebugLog, 1) end
    if AutoSteal.DebugEnabled then
        print(message)
        -- Tambem manda uma nota pro Debug do painel (se o modulo estiver la).
        local diag = env.__DEPHUB and env.__DEPHUB.Diagnostics
        if type(diag) == "table" and type(diag.Note) == "function" then
            pcall(diag.Note, diag, message)
        end
    end
end

function AutoSteal.new(context, options)
    local self = setmetatable({}, AutoSteal)
    options = options or {}
    -- Contexto compartilhado do backend (helpers de mundo). Se vier um options
    -- no lugar (compatibilidade), aceita.
    if type(context) == "table" and context.MyPen then
        self.Ctx = context
    else
        self.Ctx = options
        options = type(context) == "table" and context or options
    end
    self.Enabled = false
    self.Thread = nil
    self.LastError = nil
    self.LastStatus = "idle"
    self.Destroyed = false
    -- Steal All: uma passada unica (botao). AllThread guarda a thread viva pra
    -- nao deixar duas passadas rodarem juntas.
    self.AllThread = nil
    -- Noclip/ancoragem: guardam o estado original pra restaurar ao parar.
    self.Frozen = false
    self.OriginalAnchored = nil
    self.OriginalCollide = nil
    -- Debug: historico de log desta sessao.
    self.DebugLog = {}
    return self
end

-- O historico de debug (ultimas linhas). Util pra puxar do painel/console.
function AutoSteal:Logs()
    return self.DebugLog or {}
end

-- --- Helpers de mundo -----------------------------------------------------

local function mapFolder()
    return Workspace:FindFirstChild("Map")
end

-- A minha base: varre Pens e compara o atributo Owner com o MEU UserId. Nao usa
-- Pen1/Pen2 fixo -- a numeracao muda por servidor -- e funciona para quem
-- receber o script (UserId de cada um), nao so para mim.
function AutoSteal:MyPen()
    -- Se o backend passou o helper compartilhado, usa ele (uma logica so de
    -- Owner no repo). Senao, cai no fallback local.
    if self.Ctx and type(self.Ctx.MyPen) == "function" then
        return self.Ctx.MyPen()
    end
    local map = mapFolder()
    if not map then return nil end
    local pens = map:FindFirstChild("Pens")
    if not pens then return nil end
    local myUserId = LocalPlayer and LocalPlayer.UserId
    if not myUserId then return nil end
    -- Owner pode vir como number ou string dependendo do jogo; compara como
    -- string para nao escapar por tipo.
    local wanted = tostring(myUserId)
    for _, pen in ipairs(pens:GetChildren()) do
        local owner = pen:GetAttribute("Owner")
        if owner ~= nil and tostring(owner) == wanted then return pen end
    end
    return nil
end

-- O ponto de guardar da minha base (BadgeAnchor). Devolve a CFrame, ou nil.
function AutoSteal:PenAnchor()
    local pen = self:MyPen()
    if not pen then return nil end
    local anchor = pen:FindFirstChild("BadgeAnchor")
    if not anchor then return nil end
    if anchor:IsA("BasePart") then return anchor.CFrame end
    if anchor:IsA("Model") and anchor.PrimaryPart then return anchor.PrimaryPart.CFrame end
    return nil
end

-- TODOS os Exus do Runtime, cada um com seu Root/prompt. Os modelos sao iguais
-- (mesmo nome), entao a unica varredura confiavel e' percorrer os filhos do
-- Runtime -- e' isso que garante "pegar VARIOS", em vez de bater sempre no
-- mesmo Exu por proximidade. Devolve uma lista de {model, prompt, rootPart}.
local function runtimeExus()
    local list = {}
    local runtime = Workspace:FindFirstChild("Runtime")
    if not runtime then return list end
    for _, model in ipairs(runtime:GetChildren()) do
        local root = model:FindFirstChild("Root")
        local prompt = root and root:FindFirstChild("ProximityPrompt")
        if prompt then
            local rootPart
            if root and root:IsA("BasePart") then rootPart = root
            elseif model:IsA("Model") and model.PrimaryPart then rootPart = model.PrimaryPart
            elseif model:IsA("BasePart") then rootPart = model end
            if rootPart then
                list[#list + 1] = {model = model, prompt = prompt, rootPart = rootPart}
            end
        end
    end
    return list
end

-- --- Personagem: root, noclip e ancoragem ---------------------------------

function AutoSteal:_root()
    local character = LocalPlayer and LocalPlayer.Character
    if not character then return nil end
    return character:FindFirstChild("HumanoidRootPart")
end

function AutoSteal:_character()
    return LocalPlayer and LocalPlayer.Character
end

-- Noclip: desliga a colisao de toda BasePart do personagem (e guarda o valor
-- original pra devolver no fim). Sem isso o corpo colide com o cenario e trava.
function AutoSteal:_noclip(on)
    local character = self:_character()
    if not character then return end
    self.OriginalCollide = self.OriginalCollide or {}
    for _, part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            if on then
                if self.OriginalCollide[part] == nil then self.OriginalCollide[part] = part.CanCollide end
                part.CanCollide = false
            else
                local original = self.OriginalCollide[part]
                if original ~= nil then
                    pcall(function() part.CanCollide = original end)
                else
                    pcall(function() part.CanCollide = true end)
                end
            end
        end
    end
    if not on then self.OriginalCollide = {} end
end

-- Congela o personagem no ar: ancora o HumanoidRootPart e zera as velocidades.
-- Ancorado, ele nao cai, nao escorrega e nao briga com o teleporte. Guarda a
-- ancoragem original do Root pra restaurar.
function AutoSteal:_freeze(on)
    local root = self:_root()
    if not root then return end
    if on then
        if self.OriginalAnchored == nil then self.OriginalAnchored = root.Anchored end
        pcall(function()
            root.Anchored = true
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    else
        local original = self.OriginalAnchored
        pcall(function()
            root.Anchored = original == true
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
        self.OriginalAnchored = nil
    end
    self.Frozen = on == true
end

-- Liga noclip + congelamento. Idempotente.
function AutoSteal:_enterStealState()
    debugLog(self, "estado steal ON: noclip + ancorado (parado no ar)")
    self:_noclip(true)
    self:_freeze(true)
end

-- Restaura tudo: colisao e ancoragem originais. Idempotente.
function AutoSteal:_leaveStealState()
    debugLog(self, "estado steal OFF: colisao e ancoragem restauradas")
    self:_freeze(false)
    self:_noclip(false)
end

-- --- Teleporte instantaneo ------------------------------------------------

-- Teleporte DIRETO: escreve a CFrame no HumanoidRootPart na hora. Zera as
-- velocidades para o personagem nao seguir escorregando do teleporte anterior.
function AutoSteal:TeleportTo(cframe)
    if not cframe then return false end
    local root = self:_root()
    if not root then return false end
    pcall(function()
        root.CFrame = cframe
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    return true
end

-- --- Disparo do prompt ----------------------------------------------------

-- Rouba o Exu.
--
-- MECANISMO (confirmado em jogo, script de referencia do usuario):
--
--     prompt.HoldDuration = 0        -- <- a peca-chave
--     prompt:InputHoldBegin()
--     prompt:InputHoldEnd()
--
-- Com o HoldDuration zerado o hold completa NA HORA, e o servidor aceita o
-- roubo. Sem zerar, o InputHoldEnd chega antes de o hold real (0.5s) terminar
-- e o servidor descarta -- foi por isso que o fire e o hold completo nao
-- roubavam de forma consistente. O [PromptSpy3] mostrou que o Dex nao usa hold:
-- ele faz exatamente isto (zera o tempo e fecha o hold na hora).
--
-- Restauramos o HoldDuration original logo depois, pra nao deixar residuo no
-- prompt do jogo (regra 3: cleanup real).
--
-- Se a versao do jogo/executor nao tiver InputHoldBegin/End, cai no
-- fireproximityprompt (o antigo), pra nunca travar.
--
-- `postHold`: respiro em cima do Exu antes de voltar pra base (pro servidor
--             creditar). Devolve true se a acao foi enviada.
local function stealPrompt(prompt, postHold)
    if not prompt then return false end
    postHold = tonumber(postHold) or 0

    local hasBegin = type(prompt.InputHoldBegin) == "function"
    local hasEnd = type(prompt.InputHoldEnd) == "function"

    if hasBegin then
        -- Guarda o valor real pra restaurar depois (sem residuo).
        local original = prompt.HoldDuration
        pcall(function() prompt.HoldDuration = 0 end)

        local began = pcall(function() prompt:InputHoldBegin() end)
        if hasEnd then pcall(function() prompt:InputHoldEnd() end) end

        -- Restaura o HoldDuration do jogo assim que o roubo foi despachado.
        pcall(function() prompt.HoldDuration = original end)

        if began then
            task.wait(postHold)
            return true
        end
    end

    -- Fallback (executor/jogo sem InputHold*): o fire instantaneo.
    local fire = fireproximityprompt
    if type(fire) == "function" then
        local ok = pcall(fire, prompt)
        task.wait(postHold)
        return ok
    end
    return false
end

-- O prompt esta no alcance? (Enabled e a distancia dentro do MaxActivationDistance)
local function promptInRange(prompt, rootPosition)
    if not prompt then return false end
    if prompt.Enabled == false then return false end
    local part = prompt.Parent
    if part and part:IsA("BasePart") and rootPosition then
        local range = prompt.MaxActivationDistance or 10
        return (part.Position - rootPosition).Magnitude <= range
    end
    return true
end

-- --- O passo de roubo -----------------------------------------------------

-- Um roubo, preso a UM Exu do Runtime.
--   1) vai pra CIMA do Root do Exu (dentro do MaxActivationDistance);
--   2) zera o HoldDuration e fecha o hold (InputHoldBegin/End) -- o mecanismo
--      confirmado em jogo; o fire instantaneo nao rouba;
--   3) volta pra base pra validar.
-- `target`: {model, prompt, rootPart} (vindo de runtimeExus()).
-- options.validateWait / settleWait / postHold / label: como antes.
function AutoSteal:_stealAt(target, options)
    options = options or {}
    local label = options.label or "?"
    local anchor = self:PenAnchor()
    if not anchor then
        self.LastError = "base nao encontrada (Owner)"
        debugLog(self, label, "ABORTA: base nao encontrada (Owner)")
        return false
    end

    local prompt = target and target.prompt
    local rootPart = target and target.rootPart
    if not prompt or not rootPart then
        debugLog(self, label, "1) Exu invalido (sem Root/prompt)")
        self:TeleportTo(anchor)
        task.wait(options.validateWait or VALIDATE_WAIT)
        return false
    end

    -- 2) Teleporta pra CIMA do Root do Exu -- e o que faz o prompt valer de
    --    verdade no servidor.
    self:TeleportTo(rootPart.CFrame)
    debugLog(self, label, "2) teleportou pro Root do Exu (",
        rootPart:GetFullName(), ")")
    task.wait()

    local root = self:_root()
    local rootPos = root and root.Position or rootPart.Position
    local distance = (rootPart.Position - rootPos).Magnitude
    local range = prompt.MaxActivationDistance or 10
    debugLog(self, label, "3) dist ate o prompt=", string.format("%.1f", distance),
        "range=", tostring(prompt.MaxActivationDistance), "enabled=", tostring(prompt.Enabled))

    -- Deixa o prompt assentar (corpo parado no ar em cima do Exu).
    task.wait(options.settleWait or SETTLE_WAIT)

    if not promptInRange(prompt, rootPos) then
        debugLog(self, label, "AVISO: ainda fora do alcance (dist=",
            string.format("%.1f", distance), "range=", tostring(range), ")")
    end

    -- 4) Rouba zerando o HoldDuration e fechando o hold na hora (mecanismo
    --    confirmado em jogo), e fica em cima do Exu (postHold) pro servidor
    --    creditar antes de teleportar.
    local stolen = stealPrompt(prompt, options.postHold or POST_HOLD_WAIT)
    debugLog(self, label, "4) roubo ->", tostring(stolen),
        "HoldDuration=", tostring(prompt.HoldDuration))

    -- 5) Volta pra base e espera pra o jogo confirmar o guardar.
    self:TeleportTo(anchor)
    debugLog(self, label, "5) voltou pra base; validando por",
        tostring(options.validateWait or VALIDATE_WAIT), "s")
    task.wait(options.validateWait or VALIDATE_WAIT)

    return stolen
end

-- Um ciclo do Auto Steal Exu: varre TODOS os Exus do Runtime, roubando um por um
-- (cada um com sua ida-e-volta pra base). A varredura e' pelos filhos do Runtime
-- -- nao pelos Nests -- porque e' isso que pega VARIOS Exus: os Nests podem
-- apontar pro mesmo Exu por proximidade, e ai so um era roubado.
function AutoSteal:StealOnce()
    if not self:_root() then self.LastError = "sem personagem"; return false, 0 end
    local exus = runtimeExus()
    if #exus == 0 then
        self.LastError = "nenhum Exu no Runtime"
        debugLog(self, "ABORTA: workspace.Runtime sem Exus")
        self.LastStatus = "no targets"
        return false, 0
    end

    debugLog(self, "=== ciclo Auto Steal Exu (", tostring(#exus), "Exus) ===")
    local stole = 0
    for index = 1, #exus do
        local ok = self:_stealAt(exus[index], {
            label = "Exu" .. index,
            validateWait = VALIDATE_WAIT,
            settleWait = SETTLE_WAIT,
            postHold = POST_HOLD_WAIT,
        })
        if ok then stole = stole + 1 end
    end

    debugLog(self, "=== fim do ciclo: roubou", stole, "de", tostring(#exus), "===")
    self.LastStatus = stole > 0 and "stealing" or "no targets"
    return stole > 0, stole
end

-- --- Steal All (botao) ----------------------------------------------------

-- Uma passada por TODOS os Exus do Runtime, do ultimo pro primeiro. Mesmo ciclo
-- do toggle, so que mais rapido. No fim volta pro CFrame de origem.
function AutoSteal:StealAll()
    if not self:_root() then self.LastError = "sem personagem"; return false, 0 end

    local exus = runtimeExus()
    if #exus == 0 then
        self.LastError = "nenhum Exu no Runtime"
        debugLog(self, "ABORTA: workspace.Runtime sem Exus")
        self.LastStatus = "no targets"
        return false, 0
    end

    local origin = self:PenAnchor()
    self.LastStatus = "stealing all"
    self.LastError = nil
    local stole, skipped = 0, 0

    debugLog(self, "=== Steal All:", #exus, "Exus ===")

    -- Do ultimo pro primeiro (a ordem pedida pelo usuario para a varredura).
    for index = #exus, 1, -1 do
        local ok = self:_stealAt(exus[index], {
            label = "Exu" .. index,
            validateWait = ALL_VALIDATE_WAIT,
            settleWait = ALL_SETTLE_WAIT,
            postHold = ALL_POST_HOLD_WAIT,
        })
        if ok then stole = stole + 1 else skipped = skipped + 1 end
        task.wait(ALL_STEP_GAP)
    end

    -- Volta pra base no fim (tambem e onde o ultimo passo ja parou).
    if origin then self:TeleportTo(origin) end

    debugLog(self, "=== fim do Steal All: roubou", stole, "pulou", skipped, "===")
    self.LastStatus = "idle"
    self.LastCounts = {stole = stole, skipped = skipped}
    return stole > 0, stole
end

-- O botao chama isto: sobe a passada numa thread propria pra nao travar o
-- clique, com noclip+congelamento ligados. Uma passada por vez.
function AutoSteal:StartStealAll()
    if self.Destroyed then
        debugLog(self, "Steal All ignorado: feature destruida")
        return false
    end
    if self.AllThread then
        debugLog(self, "Steal All ignorado: ja tem uma passada rodando")
        return false
    end
    debugLog(self, "Steal All iniciado (botao)")
    self:_enterStealState()
    self.AllThread = task.spawn(function()
        local ok, err = pcall(function() return self:StealAll() end)
        if not ok then
            self.LastError = tostring(err)
            debugLog(self, "Steal All ERRO:", tostring(err))
        end
        -- So sai do estado de steal se o toggle do loop tambem nao estiver ligado.
        if not self.Enabled then self:_leaveStealState() end
        self.AllThread = nil
        debugLog(self, "Steal All terminado")
    end)
    return true
end

-- --- Ciclo de vida --------------------------------------------------------

function AutoSteal:_loop()
    debugLog(self, "loop Auto Steal Exu iniciado")
    self:_enterStealState()
    while self.Enabled do
        local done, result = pcall(function() return self:StealOnce() end)
        if not done then
            self.LastError = tostring(result)
            debugLog(self, "ciclo ERRO:", tostring(result))
        end
    end
    -- Saiu do loop: se o botao nao estiver rodando, restaura tudo.
    if not self.AllThread then self:_leaveStealState() end
    self.Thread = nil
    debugLog(self, "loop Auto Steal Exu parado")
end

function AutoSteal:SetEnabled(on)
    self.Enabled = on == true
    if not self.Enabled then
        if self.Thread then pcall(task.cancel, self.Thread); self.Thread = nil end
        self.LastStatus = "idle"
        if not self.AllThread then self:_leaveStealState() end
        return true
    end
    -- Sobe o loop so uma vez. Se ja esta rodando (toggle re-ligado), nao duplica.
    if not self.Thread then
        self.LastError = nil
        self.Thread = task.spawn(function() self:_loop() end)
    end
    return true
end

function AutoSteal:IsEnabled()
    return self.Enabled == true
end

function AutoSteal:Destroy()
    self.Destroyed = true
    self.Enabled = false
    if self.Thread then pcall(task.cancel, self.Thread); self.Thread = nil end
    if self.AllThread then pcall(task.cancel, self.AllThread); self.AllThread = nil end
    self:_leaveStealState()
end

return AutoSteal

]],
    ["src/games/features/stealanexu/autoupgrade.lua"] = [[
-- Steal An Exu -- Auto Upgrade (dois toggles: base e esteira).
--
-- A ideia e' a mesma dos dois: o jogo sobe o nivel quando o jogador clica no
-- ClickDetector do quadro do proprio pen. Entao, ligado, a gente martela esse
-- ClickDetector.
--
--   base   -> workspace.Map.Pens.<MeuPen>.PenSign.Board.ClickDetector
--   esteira-> workspace.Map.Pens.<MeuPen>.TreadSign.Board.ClickDetector
--
-- "A base muda": NUNCA usa Pen1/Pen2 fixo -- o pen e' sempre o MEU, achado pelo
-- atributo Owner (mesma logica do autosteal, vinda do contexto do backend).
--
-- Os dois quadros sao o MESMO mecanismo mudando so o caminho dentro do pen, entao
-- este modulo e' uma fabrica: o backend instancia duas vezes (base e esteira),
-- cada uma com seu toggle.
--
-- API: AutoUpgrade.new(ctx, opts) -> obj com SetEnabled(on) / IsEnabled() /
--      Destroy() e o campo Enabled.

local game = game
local task = task
local type = type
local pcall = pcall
local tostring = tostring
local table = table
local select = select

-- De quanto em quanto tempo clicar. O upgrade tem custo/animacao; martelar mais
-- rapido que isso so desperdica chamada (o servidor ignora as repetidas).
local CLICK_INTERVAL = 0.3

local AutoUpgrade = {}
AutoUpgrade.__index = AutoUpgrade

-- --- Debug ----------------------------------------------------------------

AutoUpgrade.DebugEnabled = true
local DEBUG_TAG = "[StealAnExu]"
local env = type(getgenv) == "function" and getgenv() or _G

local function debugLog(self, ...)
    local parts = {}
    for index = 1, select("#", ...) do
        parts[#parts + 1] = tostring(select(index, ...))
    end
    local message = DEBUG_TAG .. " " .. self.Label .. ": " .. table.concat(parts, " ")
    self.DebugLog = self.DebugLog or {}
    self.DebugLog[#self.DebugLog + 1] = message
    if #self.DebugLog > 200 then table.remove(self.DebugLog, 1) end
    if AutoUpgrade.DebugEnabled then
        print(message)
        local diag = env.__DEPHUB and env.__DEPHUB.Diagnostics
        if type(diag) == "table" and type(diag.Note) == "function" then
            pcall(diag.Note, diag, message)
        end
    end
end

-- --- Construtor -----------------------------------------------------------

-- ctx: contexto compartilhado do backend (ctx.MyPen / ctx.PenPart).
-- opts.label: prefixo do log ("base" / "tread").
-- opts.path:  caminho pontuado dentro do pen ate o ClickDetector.
function AutoUpgrade.new(ctx, opts)
    opts = opts or {}
    local self = setmetatable({}, AutoUpgrade)
    self.Ctx = ctx or {}
    self.Label = opts.label or "upgrade"
    self.Path = opts.path
    self.Enabled = false
    self.Thread = nil
    self.LastError = nil
    self.Destroyed = false
    self.DebugLog = {}
    return self
end

function AutoUpgrade:Logs()
    return self.DebugLog or {}
end

function AutoUpgrade:IsEnabled()
    return self.Enabled == true
end

-- --- O alvo ---------------------------------------------------------------

-- O ClickDetector da minha base pra este upgrade. Se o objeto no fim do caminho
-- nao for um ClickDetector (o jogo as vezes troca por outro "botao"), ainda
-- aceita qualquer coisa com :Click().
function AutoUpgrade:Detector()
    local ctx = self.Ctx
    if type(ctx.PenPart) ~= "function" then
        return nil, "sem helper de mundo (ctx.PenPart ausente)"
    end
    local instance = ctx.PenPart(self.Path)
    if not instance then
        return nil, "caminho nao encontrado no meu pen: " .. tostring(self.Path)
    end
    if instance:IsA("ClickDetector") then return instance end
    -- Alguns jogos poem um filho ClickDetector dentro do "Board"; aceita.
    local child = instance:FindFirstChildOfClass("ClickDetector")
    if child then return child end
    -- Ultimo caso: um objeto com :Click() (funciona igual no client).
    if type(instance.Click) == "function" then return instance end
    return nil, "nao e um ClickDetector: " .. instance:GetFullName()
end

-- Um clique. Prefere o fireclickdetector do executor (e o que atravessa o
-- filtro do client sem depender de toque); cai no :Click() se nao houver.
function AutoUpgrade:Click(detector)
    if not detector then return false end
    local fire = fireclickdetector
    if type(fire) == "function" then
        local ok = pcall(fire, detector)
        if ok then return true end
    end
    if type(detector.Click) == "function" then
        local ok = pcall(function() detector:Click() end)
        if ok then return true end
    end
    return false
end

-- --- O loop ---------------------------------------------------------------

function AutoUpgrade:_loop()
    debugLog(self, "loop de upgrade iniciado (", tostring(self.Path), ")")
    local misses = 0
    while self.Enabled do
        local detector, reason = self:Detector()
        if detector then
            misses = 0
            local ok = self:Click(detector)
            if not ok then
                self.LastError = "falha ao clicar"
                debugLog(self, "clique falhou em", detector:GetFullName())
            end
        else
            -- Base/path ausente e' normal enquanto o pen ainda esta carregando;
            -- so loga de vez em quando pra nao inundar o console.
            misses = misses + 1
            self.LastError = reason
            if misses == 1 or misses % 20 == 0 then
                debugLog(self, "sem alvo (", tostring(reason), ") tentativa", misses)
            end
        end
        task.wait(CLICK_INTERVAL)
    end
    self.Thread = nil
    debugLog(self, "loop de upgrade parado")
end

-- --- Ligar / desligar -----------------------------------------------------

-- Idempotente: ligar duas vezes nao abre dois loops, desligar duas vezes nao
-- quebra. Nao deixa residuo: ao desligar, a thread sai no proximo tick.
function AutoUpgrade:SetEnabled(on)
    on = on == true
    if self.Destroyed then
        debugLog(self, "SetEnabled ignorado: feature destruida")
        return false
    end
    if on == self.Enabled then return true end
    self.Enabled = on
    if on then
        debugLog(self, "ON")
        self.Thread = task.spawn(function()
            local ok, err = pcall(function() return self:_loop() end)
            if not ok then
                self.LastError = tostring(err)
                debugLog(self, "ERRO no loop:", tostring(err))
            end
        end)
    else
        debugLog(self, "OFF")
    end
    return true
end

function AutoUpgrade:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    self.Enabled = false
    if self.Thread then
        pcall(task.cancel, self.Thread)
        self.Thread = nil
    end
    self.DebugLog = {}
end

-- Devolve a fabrica.
return AutoUpgrade

]],
