            DashBlock=context.DashBlock==true,SkillBlock=context.SkillBlock==true,FacingCheck=context.FacingCheck~=false,
            Prediction=context.Prediction~=false,UnknownLogger=context.UnknownLogger==true,ShowDetectionBox=context.ShowDetectionBox==true,
            Debug=context.Debug==true,NormalRange=clamp(tonumber(context.NormalRange) or 12,2,30),
            SpecialRange=clamp(tonumber(context.SpecialRange) or 50,5,80),SkillRange=clamp(tonumber(context.SkillRange) or 50,5,80),
            SkillHold=clamp(tonumber(context.SkillHold) or 1.2,0.1,2),DetectionBoxSize=clamp(tonumber(context.DetectionBoxSize) or 12,2,40),
            ScanHz=clamp(tonumber(context.ScanHz) or 45,10,60),CounterRange=clamp(tonumber(context.CounterRange) or 10,2,20),
            CounterDelay=clamp(tonumber(context.CounterDelay) or 0.07,0.02,0.35),AttackGrace=clamp(tonumber(context.AttackGrace) or 0.08,0,0.3),
            FacingDot=clamp(tonumber(context.FacingDot) or -0.05,-1,1),PredictionTime=clamp(tonumber(context.PredictionTime) or 0.12,0,0.35),
            PredictionExtra=clamp(tonumber(context.PredictionExtra) or 3,0,8)
