            LastDistance=0,LastPredictedDistance=0,LastFacing=0,LastClosingSpeed=0,Blocks=0,Releases=0,Counters=0,CameraLocks=0,
            AnimationEvents=0,M1Events=0,TrackedPlayers=0,KnownSkillAnimations=knownSkillCount,UnknownAnimations=0,PredictionBlocks=0,FacingRejected=0,
            ScanHz=clamp(tonumber(context.ScanHz) or 45,10,60),LastError="none",LocalAttacking=false,Mouse1Down=false,LocalM1ing=false,
