    end
    function self:_setError(message)
        self.DebugInfo.LastError=tostring(message or "none")
        if message and self.Config.Debug then warn("[DepHub TSB] "..tostring(message)) end
    end
    function self:_localCharacter() return LocalPlayer and LocalPlayer.Character or nil end
    function self:_localRoot() local character=self:_localCharacter() return character and character:FindFirstChild("HumanoidRootPart") or nil end
    function self:_localAlive()
        local character=self:_localCharacter()
        local humanoid=character and character:FindFirstChildWhichIsA("Humanoid")
