        self.LocalConnections[#self.LocalConnections+1]=character.DescendantAdded:Connect(function(instance) if instance.Name=="M1ing" then self:_setLocalM1ing(true) end end)
        self.LocalConnections[#self.LocalConnections+1]=character.DescendantRemoving:Connect(function(instance)
            if instance.Name~="M1ing" then return end
            task.defer(function() if self.Destroyed or not self.Enabled or LocalPlayer.Character~=character then return end self:_setLocalM1ing(character:FindFirstChild("M1ing",true)~=nil) end)
        end)
        local okTracks,tracks=pcall(animator.GetPlayingAnimationTracks,animator)
        if okTracks and type(tracks)=="table" then for _,track in ipairs(tracks) do self:_trackLocalAnimation(track) end end
        self:_refreshLocalAttackDebug()
    end
    function self:_communicate(goal,mobile)
        if self.Destroyed or not LocalPlayer then return false end
        local character=LocalPlayer.Character local remote=character and character:FindFirstChild("Communicate")
        self.DebugInfo.Character=character and character.Name or "none" self.DebugInfo.Remote=remote and remote:IsA("RemoteEvent") and "ready" or "missing"
        if not remote or not remote:IsA("RemoteEvent") then return false end
        local payload={Goal=goal} if mobile==true then payload.Mobile=true end if goal=="KeyPress" or goal=="KeyRelease" then payload.Key=Enum.KeyCode.F end
        local ok,errorMessage=pcall(remote.FireServer,remote,payload)
        if not ok then self:_setError(errorMessage) return false end
        self.DebugInfo.LastError="none" return true
    end
    function self:_leftClickOnce()
        if self.Destroyed or not self.Enabled or not self:_localAlive() then return false end
        if self:_isLocalAttacking() then self.DebugInfo.SuppressedCounters=self.DebugInfo.SuppressedCounters+1 return false end
        if not self:_communicate("LeftClick",true) then return false end
        local character=LocalPlayer.Character
        local remote=character and character:FindFirstChild("Communicate")
