            if remote and remote.Parent then pcall(remote.FireServer,remote,{Goal="LeftClickRelease",Mobile=true}) end
        end)
        return true
    end
    function self:_destroyDetectionBox()
        local part=self.DetectionPart self.DetectionPart=nil self.DetectionCharacter=nil if part then pcall(part.Destroy,part) end
    end
    function self:_ensureDetectionBox()
        local character=self:_localCharacter() local root=character and character:FindFirstChild("HumanoidRootPart")
        if not character or not root then return nil end
        local size=self.Config.DetectionBoxSize local part=self.DetectionPart
        if part and part.Parent and self.DetectionCharacter==character then part.Size=Vector3.new(size,size,size) part.Transparency=self.Config.ShowDetectionBox and 0.68 or 1 return part end
        self:_destroyDetectionBox()
        part=Instance.new("Part") part.Name="DepHubDetectionBox" part.Size=Vector3.new(size,size,size) part.CFrame=root.CFrame part.Color=Color3.fromRGB(255,55,55) part.Material=Enum.Material.Plastic
        part.Transparency=self.Config.ShowDetectionBox and 0.68 or 1 part.CanCollide=false part.CanTouch=false part.CanQuery=false part.CastShadow=false part.Massless=true part.Anchored=false part.Parent=character
        local weld=Instance.new("WeldConstraint") weld.Part0=root weld.Part1=part weld.Parent=part self.DetectionPart=part self.DetectionCharacter=character return part
    end
    function self:_insideDetectionBoxPosition(enemyPosition,myRoot)
        if not enemyPosition or not myRoot then return false end
        local relative=myRoot.CFrame:PointToObjectSpace(enemyPosition) local half=self.Config.DetectionBoxSize*0.5
        return math_abs(relative.X)<=half and math_abs(relative.Y)<=half and math_abs(relative.Z)<=half
    end
    function self:_insideDetectionBox(enemyRoot,myRoot) return enemyRoot~=nil and self:_insideDetectionBoxPosition(enemyRoot.Position,myRoot) end
    function self:_threatMetrics(tracker,myRoot,range,requireBox,requireFacing)
        if not tracker or not tracker.Root or not tracker.Root.Parent or not myRoot then return nil end
        local enemyRoot=tracker.Root local delta=myRoot.Position-enemyRoot.Position local distance=delta.Magnitude
        local direction=flatUnit(delta) local look=flatUnit(enemyRoot.CFrame.LookVector) local facing=(direction and look) and look:Dot(direction) or 1
        local predictionTime=self.Config.Prediction and self.Config.PredictionTime or 0
        local enemyVelocity=enemyRoot.AssemblyLinearVelocity or Vector3.zero local myVelocity=myRoot.AssemblyLinearVelocity or Vector3.zero
        local predictedEnemy=enemyRoot.Position+enemyVelocity*predictionTime local predictedMine=myRoot.Position+myVelocity*predictionTime
        local predictedDistance=(predictedMine-predictedEnemy).Magnitude local closingSpeed=predictionTime>0 and (distance-predictedDistance)/predictionTime or 0
        local facingPass=not requireFacing or not self.Config.FacingCheck or facing>=self.Config.FacingDot
        local insideNow=not requireBox or self:_insideDetectionBox(enemyRoot,myRoot) local insidePredicted=true
        if requireBox then local translated=predictedEnemy+(myRoot.Position-predictedMine) insidePredicted=self:_insideDetectionBoxPosition(translated,myRoot) end
        local nowPass=distance<=range and insideNow local predictionPass=false
        if self.Config.Prediction and predictionTime>0 and closingSpeed>0 then predictionPass=distance<=range+self.Config.PredictionExtra and predictedDistance<=range and insidePredicted end
        self.DebugInfo.LastDistance=distance self.DebugInfo.LastPredictedDistance=predictedDistance self.DebugInfo.LastFacing=facing self.DebugInfo.LastClosingSpeed=closingSpeed
        if not facingPass and (nowPass or predictionPass) then self.DebugInfo.FacingRejected=self.DebugInfo.FacingRejected+1 end
        return {Pass=facingPass and (nowPass or predictionPass),Predicted=not nowPass and predictionPass,Distance=distance,PredictedDistance=predictedDistance,Facing=facing,ClosingSpeed=closingSpeed}
    end
    function self:_beginCameraLock(player,tracker)
        if not self.Config.FaceAttacker or not tracker or not tracker.Root or not tracker.Root.Parent then return false end
        local camera=Workspace.CurrentCamera if not camera then return false end
        if not self.CameraLockActive then self.CameraSnapshot={Camera=camera,CFrame=camera.CFrame} self.CameraLockActive=true self.DebugInfo.CameraLocks=self.DebugInfo.CameraLocks+1 end
        self.BlockTargetPlayer=player self.BlockTargetTracker=tracker return true
    end
    function self:_restoreCamera()
        if not self.CameraLockActive then self.CameraSnapshot=nil return end
        self.CameraLockActive=false local snapshot=self.CameraSnapshot self.CameraSnapshot=nil
        if snapshot and snapshot.Camera and snapshot.Camera.Parent and snapshot.CFrame then
            local camera=snapshot.Camera local saved=snapshot.CFrame pcall(function() camera.CFrame=saved end)
            task.defer(function() if not self.Destroyed and camera and camera.Parent and not self.CameraLockActive then pcall(function() camera.CFrame=saved end) end end)
        end
    end
    function self:_updateCameraLock()
        if self.Destroyed or not self.Enabled or not self.CameraLockActive or not self.BlockActive then return end
        local tracker=self.BlockTargetTracker local targetRoot=tracker and tracker.Root local camera=Workspace.CurrentCamera
        if not targetRoot or not targetRoot.Parent or not camera then return end
        local origin=camera.CFrame.Position local target=targetRoot.Position+Vector3.new(0,1.5,0) if (target-origin).Magnitude<0.01 then return end
        pcall(function() camera.CFrame=CFrame.lookAt(origin,target) end)
