    function self:_queueCounter()
        if not self.Config.M1AfterBlock or not self.CounterPending then return end
        local tracker=self.BlockTargetTracker local player=self.BlockTargetPlayer self.CounterPending=false self.CounterToken=self.CounterToken+1
        local token=self.CounterToken local characterToken=self.CharacterToken
