        tracker.Connections[#tracker.Connections+1]=character.DescendantAdded:Connect(function(instance) if tracker.Destroyed or instance.Name~="M1ing" then return end tracker.M1ing=true tracker.InsideLast=false self.DebugInfo.M1Events=self.DebugInfo.M1Events+1 self:_handleM1(player,tracker,"M1ing") end)
        tracker.Connections[#tracker.Connections+1]=character.DescendantRemoving:Connect(function(instance)
            if tracker.Destroyed or instance.Name~="M1ing" then return end
            task.defer(function() if tracker.Destroyed or not tracker.Character.Parent then return end tracker.M1ing=tracker.Character:FindFirstChild("M1ing",true)~=nil if not tracker.M1ing then tracker.InsideLast=false end end)
        end)
        local okTracks,tracks=pcall(animator.GetPlayingAnimationTracks,animator) if okTracks and type(tracks)=="table" then for _,track in ipairs(tracks) do self:_registerTrack(player,tracker,track,true) end end
        if tracker.M1ing then self:_handleM1(player,tracker,"M1ing existing") end
    end
    function self:_queueCharacter(player,binding,character)
        if not binding then return end
        binding.Generation=binding.Generation+1
        binding.Character=character
        disconnectAll(binding.CharacterConnections)
        self:_destroyTracker(binding)
        if not character then return end
        local generation=binding.Generation
        local function refresh()
            if self.Destroyed or not self.Enabled or self.PlayerBindings[player]~=binding or binding.Generation~=generation then return end
            local humanoid=character:FindFirstChildWhichIsA("Humanoid")
            local root=character:FindFirstChild("HumanoidRootPart")
            local animator=humanoid and humanoid:FindFirstChildOfClass("Animator")
            local tracker=binding.Tracker
            if tracker and tracker.Humanoid==humanoid and tracker.Root==root and tracker.Animator==animator then return end
            self:_destroyTracker(binding)
            if humanoid and root and animator then self:_attachTracker(player,binding,character,humanoid,root,animator) end
        end
        local pending=false
        local function schedule(instance)
            if instance.Name~="HumanoidRootPart" and not instance:IsA("Humanoid") and not instance:IsA("Animator") then return end
            if pending then return end
            pending=true
            task.defer(function() pending=false; refresh() end)
        end
