    ["src/games/features/tsb/autoblock.lua"] = [[
local game = game
local task = task
local type = type
local tonumber = tonumber
local tostring = tostring
local ipairs = ipairs
local pairs = pairs
local math_max = math.max
local math_min = math.min
local math_abs = math.abs
local math_floor = math.floor
local os_clock = os.clock

local Factory = {}

local function disconnectAll(list)
    if not list then return end
    for index = #list, 1, -1 do
        local connection = list[index]
        list[index] = nil
        if connection then
            pcall(connection.Disconnect, connection)
        end
    end
end

local function clamp(value, minimum, maximum)
    return math_min(maximum, math_max(minimum, value))
end

local function getAnimationId(track)
    if not track then return nil end
    local okAnimation, animation = pcall(function()
        return track.Animation
    end)
    if not okAnimation or not animation then return nil end

    local okId, rawId = pcall(function()
        return animation.AnimationId
    end)
    if not okId or type(rawId) ~= "string" then return nil end
    return tonumber(rawId:match("%d+"))
end

local function makeSet(list)
    local result = {}
    if type(list) ~= "table" then return result end
    for _, value in ipairs(list) do
        local id = tonumber(value)
        if id then result[id] = true end
    end
    return result
end

function Factory.new(context)
    context = context or {}

    local Players = context.Players or game:GetService("Players")
    local RunService = context.RunService or game:GetService("RunService")
    local Workspace = context.Workspace or game:GetService("Workspace")
    local LocalPlayer = context.LocalPlayer or Players.LocalPlayer
    local AnimationData = type(context.AnimationData) == "table" and context.AnimationData or {}

    local groups = type(AnimationData.Groups) == "table" and AnimationData.Groups or {}
    local comboIds = makeSet(AnimationData.ComboIds)
    local skillIds = makeSet(AnimationData.SkillIds)
    local normalToGroup = {}
    local specialIds = {}
    local knownSkillCount = 0

    for id in pairs(skillIds) do
        knownSkillCount = knownSkillCount + 1
    end

    for groupIndex, group in ipairs(groups) do
        if type(group) == "table" then
            local normal = type(group.Normal) == "table" and group.Normal or {}
            for _, value in ipairs(normal) do
                local id = tonumber(value)
                if id then normalToGroup[id] = groupIndex end
            end
            local special = tonumber(group.Special)
            if special then specialIds[special] = true end
        end
    end

    local self = {
        Enabled = false,
        Destroyed = false,
        Connections = {},
        PlayerBindings = {},
        DetectionPart = nil,
        DetectionCharacter = nil,
        CharacterToken = 0,
        BlockActive = false,
        BlockUntil = 0,
        BlockSource = nil,
        BlockTargetPlayer = nil,
        BlockTargetTracker = nil,
        CameraSnapshot = nil,
        CameraLockActive = false,
        CounterPending = false,
        CounterToken = 0,
        ScanAccumulator = 0,
        RenderStepName = "DepHubTSBCamera_" .. tostring(LocalPlayer and LocalPlayer.UserId or "local"),
        RenderBound = false,
        Config = {
            M1Block = context.M1Block == true,
            M1AfterBlock = context.M1AfterBlock == true,
            FaceAttacker = context.FaceAttacker ~= false,
            DashBlock = context.DashBlock == true,
            SkillBlock = context.SkillBlock == true,
            ShowDetectionBox = context.ShowDetectionBox == true,
            Debug = context.Debug == true,
            NormalRange = clamp(tonumber(context.NormalRange) or 12, 2, 30),
            SpecialRange = clamp(tonumber(context.SpecialRange) or 50, 5, 80),
            SkillRange = clamp(tonumber(context.SkillRange) or 50, 5, 80),
            SkillHold = clamp(tonumber(context.SkillHold) or 1.2, 0.1, 2),
            DetectionBoxSize = clamp(tonumber(context.DetectionBoxSize) or 12, 2, 40),
            ScanHz = clamp(tonumber(context.ScanHz) or 30, 10, 60),
            CounterRange = clamp(tonumber(context.CounterRange) or 10, 2, 20)
        },
        DebugInfo = {
            Runtime = "idle",
            Character = "none",
            Remote = "missing",
            Live = "missing",
            LastEvent = "none",
            LastReason = "none",
            LastAnimation = "none",
            LastPlayer = "none",
            LastDistance = 0,
            Blocks = 0,
            Releases = 0,
            Counters = 0,
            CameraLocks = 0,
            AnimationEvents = 0,
            M1Events = 0,
            TrackedPlayers = 0,
            KnownSkillAnimations = knownSkillCount,
            ScanHz = clamp(tonumber(context.ScanHz) or 30, 10, 60),
            LastError = "none"
        }
    }

    function self:_debug(message)
        self.DebugInfo.LastEvent = tostring(message)
        if self.Config.Debug then
            print("[DepHub TSB] " .. tostring(message))
        end
    end

    function self:_setError(message)
        self.DebugInfo.LastError = tostring(message or "none")
        if message and self.Config.Debug then
            print("[DepHub TSB] error: " .. tostring(message))
        end
    end

    function self:_localCharacter()
        return LocalPlayer and LocalPlayer.Character or nil
    end

    function self:_localRoot()
        local character = self:_localCharacter()
        return character and character:FindFirstChild("HumanoidRootPart") or nil
    end

    function self:_localAlive()
        local character = self:_localCharacter()
        local humanoid = character and character:FindFirstChildWhichIsA("Humanoid")
        return humanoid ~= nil and humanoid.Health > 0
    end

    function self:_communicate(goal, mobile)
        if self.Destroyed or not LocalPlayer then return false end

        local character = LocalPlayer.Character
        local remote = character and character:FindFirstChild("Communicate")

        self.DebugInfo.Character = character and character.Name or "none"
        self.DebugInfo.Remote = remote and remote:IsA("RemoteEvent") and "ready" or "missing"

        if not remote or not remote:IsA("RemoteEvent") then
            return false
        end

        local payload = {Goal = goal}
        if mobile == true then payload.Mobile = true end
        if goal == "KeyPress" or goal == "KeyRelease" then
            payload.Key = Enum.KeyCode.F
        end

        local ok, err = pcall(remote.FireServer, remote, payload)
        if not ok then
            self:_setError(err)
            return false
        end

        self.DebugInfo.LastError = "none"
        return true
    end

    function self:_leftClickOnce()
        if self.Destroyed or not self.Enabled or not self:_localAlive() then return false end
        if not self:_communicate("LeftClick", true) then return false end

        local token = self.CounterToken
        task.delay(0.07, function()
            if self.Destroyed or token ~= self.CounterToken then return end
            self:_communicate("LeftClickRelease", true)
        end)

        return true
    end

    function self:_destroyDetectionBox()
        local part = self.DetectionPart
        self.DetectionPart = nil
        self.DetectionCharacter = nil
        if part then
            pcall(part.Destroy, part)
        end
    end

    function self:_ensureDetectionBox()
        local character = self:_localCharacter()
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not character or not root then return nil end

        local size = self.Config.DetectionBoxSize
        local part = self.DetectionPart

        if part and part.Parent and self.DetectionCharacter == character then
            part.Size = Vector3.new(size, size, size)
            part.Transparency = self.Config.ShowDetectionBox and 0.68 or 1
            return part
        end

        self:_destroyDetectionBox()

        part = Instance.new("Part")
        part.Name = "DepHubDetectionBox"
        part.Size = Vector3.new(size, size, size)
        part.CFrame = root.CFrame
        part.Color = Color3.fromRGB(255, 55, 55)
        part.Material = Enum.Material.Plastic
        part.Transparency = self.Config.ShowDetectionBox and 0.68 or 1
        part.CanCollide = false
        part.CanTouch = false
        part.CanQuery = false
        part.CastShadow = false
        part.Massless = true
        part.Anchored = false
        part.Parent = character

        local weld = Instance.new("WeldConstraint")
        weld.Part0 = root
        weld.Part1 = part
        weld.Parent = part

        self.DetectionPart = part
        self.DetectionCharacter = character
        return part
    end

    function self:_insideDetectionBox(enemyRoot, myRoot)
        if not enemyRoot or not myRoot then return false end
        local relative = myRoot.CFrame:PointToObjectSpace(enemyRoot.Position)
        local half = self.Config.DetectionBoxSize * 0.5
        return math_abs(relative.X) <= half
            and math_abs(relative.Y) <= half
            and math_abs(relative.Z) <= half
    end

    function self:_beginCameraLock(player, tracker)
        if not self.Config.FaceAttacker or not tracker or not tracker.Root or not tracker.Root.Parent then
            return false
        end

        local camera = Workspace.CurrentCamera
        if not camera then return false end

        if not self.CameraLockActive then
            self.CameraSnapshot = {
                Camera = camera,
                CFrame = camera.CFrame
            }
            self.CameraLockActive = true
            self.DebugInfo.CameraLocks = self.DebugInfo.CameraLocks + 1
        end

        self.BlockTargetPlayer = player
        self.BlockTargetTracker = tracker
        return true
    end

    function self:_restoreCamera()
        if not self.CameraLockActive then
            self.CameraSnapshot = nil
            return
        end

        self.CameraLockActive = false
        local snapshot = self.CameraSnapshot
        self.CameraSnapshot = nil

        if snapshot and snapshot.Camera and snapshot.Camera.Parent and snapshot.CFrame then
            local camera = snapshot.Camera
            local saved = snapshot.CFrame
            pcall(function()
                camera.CFrame = saved
            end)
            task.defer(function()
                if not self.Destroyed and camera and camera.Parent and not self.CameraLockActive then
                    pcall(function()
                        camera.CFrame = saved
                    end)
                end
            end)
        end
    end

    function self:_updateCameraLock()
        if self.Destroyed or not self.Enabled or not self.CameraLockActive or not self.BlockActive then return end
        local tracker = self.BlockTargetTracker
        local targetRoot = tracker and tracker.Root
        local camera = Workspace.CurrentCamera

        if not targetRoot or not targetRoot.Parent or not camera then
            return
        end

        local origin = camera.CFrame.Position
        local target = targetRoot.Position + Vector3.new(0, 1.5, 0)
        if (target - origin).Magnitude < 0.01 then return end

        pcall(function()
            camera.CFrame = CFrame.lookAt(origin, target)
        end)
    end

    function self:_queueCounter()
        if not self.Config.M1AfterBlock or not self.CounterPending then return end

        local tracker = self.BlockTargetTracker
        local player = self.BlockTargetPlayer
        self.CounterPending = false
        self.CounterToken = self.CounterToken + 1
        local token = self.CounterToken
        local characterToken = self.CharacterToken

        task.delay(0.04, function()
            if self.Destroyed or not self.Enabled or not self.Config.M1AfterBlock then return end
            if token ~= self.CounterToken or characterToken ~= self.CharacterToken then return end
            if not tracker or tracker.Destroyed or not tracker.Root or not tracker.Root.Parent then return end

            local myRoot = self:_localRoot()
            if not myRoot then return end

            local distance = (tracker.Root.Position - myRoot.Position).Magnitude
            if distance > self.Config.CounterRange then return end

            if self:_leftClickOnce() then
                self.DebugInfo.Counters = self.DebugInfo.Counters + 1
                self:_debug("counter M1: " .. tostring(player and player.Name or "unknown"))
            end
        end)
    end

    function self:_releaseBlock(reason)
        if not self.BlockActive then
            self.BlockUntil = 0
            self.BlockSource = nil
            self.BlockTargetPlayer = nil
            self.BlockTargetTracker = nil
            self.CounterPending = false
            self:_restoreCamera()
            return false
        end

        self:_communicate("KeyRelease")
        self.BlockActive = false
        self.BlockUntil = 0
        self.BlockSource = nil
        self.DebugInfo.Releases = self.DebugInfo.Releases + 1

        self:_restoreCamera()
        self:_queueCounter()

        self.BlockTargetPlayer = nil
        self.BlockTargetTracker = nil

        if reason then
            self:_debug("block release: " .. tostring(reason))
        end

        return true
    end

    function self:_pressBlock(duration, source, reason, player, tracker, animationId, distance)
        if self.Destroyed or not self.Enabled or not self:_localAlive() then
            return false, false
        end

        local now = os_clock()
        local hold = clamp(tonumber(duration) or 0.15, 0.05, 3)
        self.BlockUntil = math_max(self.BlockUntil, now + hold)
        self.BlockSource = source or self.BlockSource or "unknown"
        self.BlockTargetPlayer = player or self.BlockTargetPlayer
        self.BlockTargetTracker = tracker or self.BlockTargetTracker
        self.CounterPending = self.Config.M1AfterBlock == true

        self.DebugInfo.LastReason = tostring(reason or source or "unknown")
        self.DebugInfo.LastAnimation = animationId and tostring(animationId) or "none"
        self.DebugInfo.LastPlayer = player and player.Name or "none"
        self.DebugInfo.LastDistance = tonumber(distance) or 0

        if tracker then
            self:_beginCameraLock(player, tracker)
        end

        if self.BlockActive then
            return true, false
        end

        if not self:_communicate("KeyPress") then
            self.BlockUntil = 0
            self.BlockSource = nil
            self.BlockTargetPlayer = nil
            self.BlockTargetTracker = nil
            self.CounterPending = false
            self:_restoreCamera()
            return false, false
        end

        self.BlockActive = true
        self.DebugInfo.Blocks = self.DebugInfo.Blocks + 1
        return true, true
    end

    function self:_trackerReady(tracker)
        if not tracker or not tracker.Character or not tracker.Character.Parent then return false end
        if not tracker.Root or not tracker.Root.Parent then return false end
        if not tracker.Humanoid or tracker.Humanoid.Health <= 0 then return false end

        local live = Workspace:FindFirstChild("Live")
        self.DebugInfo.Live = live and "ready" or "missing"
        if not live then return false end
        return tracker.Character.Parent == live
    end

    function self:_distance(tracker)
        if not self:_trackerReady(tracker) then return nil, nil end
        local myRoot = self:_localRoot()
        if not myRoot then return nil, nil end
        return (tracker.Root.Position - myRoot.Position).Magnitude, myRoot
    end

    function self:_activeCount(tracker, set)
        local count = 0
        for id in pairs(set) do
            if (tracker.ActiveIds[id] or 0) > 0 then
                count = count + 1
            end
        end
        return count
    end

    function self:_groupActiveNormals(tracker, group)
        local count = 0
        if type(group) ~= "table" or type(group.Normal) ~= "table" then return 0 end
        for _, value in ipairs(group.Normal) do
            local id = tonumber(value)
            if id and (tracker.ActiveIds[id] or 0) > 0 then
                count = count + 1
            end
        end
        return count
    end

    function self:_checkDashCombo(player, tracker, distance)
        if not self.Config.DashBlock or distance > self.Config.SpecialRange then return false end
        if self:_activeCount(tracker, comboIds) < 2 then return false end

        for _, group in ipairs(groups) do
            if self:_groupActiveNormals(tracker, group) >= 2 then
                self:_pressBlock(0.7, "dash", "combo/dash", player, tracker, nil, distance)
                return true
            end
        end

        return false
    end

    function self:_handleM1(player, tracker, reason)
        if not self.Config.M1Block or not self:_trackerReady(tracker) then return false end

        local distance, myRoot = self:_distance(tracker)
        if not distance or distance > self.Config.NormalRange then return false end
        if not self:_insideDetectionBox(tracker.Root, myRoot) then return false end

        local ok = self:_pressBlock(0.15, "m1", reason or "M1ing", player, tracker, nil, distance)
        if ok then
            tracker.InsideLast = true
        end
        return ok
    end

    function self:_handleAnimation(player, tracker, animationId)
        if not self:_trackerReady(tracker) then return end

        local distance, myRoot = self:_distance(tracker)
        if not distance or not myRoot then return end

        if self:_checkDashCombo(player, tracker, distance) then
            return
        end

        local groupIndex = normalToGroup[animationId]
        if groupIndex and self.Config.M1Block then
            if distance <= self.Config.NormalRange and self:_insideDetectionBox(tracker.Root, myRoot) then
                self:_pressBlock(0.15, "m1", "M1 animation", player, tracker, animationId, distance)
                return
            end
        end

        if specialIds[animationId] and distance <= self.Config.SpecialRange and self.Config.DashBlock then
            self:_pressBlock(1, "dash", "special/dash", player, tracker, animationId, distance)
            return
        end

        if self.Config.SkillBlock and skillIds[animationId] and distance <= self.Config.SkillRange then
            self:_pressBlock(self.Config.SkillHold, "skill", "skill", player, tracker, animationId, distance)
        end
    end

    function self:_registerTrack(player, tracker, track, process)
        if not tracker or not track or tracker.TrackIds[track] then return end

        local animationId = getAnimationId(track)
        if not animationId then return end

        tracker.TrackIds[track] = animationId
        tracker.ActiveIds[animationId] = (tracker.ActiveIds[animationId] or 0) + 1
        self.DebugInfo.AnimationEvents = self.DebugInfo.AnimationEvents + 1

        local okConnect, connection = pcall(function()
            return track.Stopped:Connect(function()
                if tracker.Destroyed then return end
                local storedId = tracker.TrackIds[track]
                tracker.TrackIds[track] = nil

                local storedConnection = tracker.TrackConnections[track]
                tracker.TrackConnections[track] = nil
                if storedConnection then
                    pcall(storedConnection.Disconnect, storedConnection)
                end

                if storedId then
                    local count = (tracker.ActiveIds[storedId] or 1) - 1
                    if count <= 0 then
                        tracker.ActiveIds[storedId] = nil
                    else
                        tracker.ActiveIds[storedId] = count
                    end
                end
            end)
        end)

        if okConnect and connection then
            tracker.TrackConnections[track] = connection
        end

        if process ~= false then
            self:_handleAnimation(player, tracker, animationId)
        end
    end

    function self:_destroyTracker(binding)
        local tracker = binding and binding.Tracker
        if not tracker then return end
        binding.Tracker = nil
        tracker.Destroyed = true

        if self.BlockTargetTracker == tracker then
            self:_releaseBlock("target removed")
        end

        disconnectAll(tracker.Connections)
        for track, connection in pairs(tracker.TrackConnections) do
            tracker.TrackConnections[track] = nil
            if connection then
                pcall(connection.Disconnect, connection)
            end
        end
    end

    function self:_attachTracker(player, binding, character, humanoid, root, animator)
        if self.Destroyed or not self.Enabled or not binding or binding.Character ~= character then return end

        self:_destroyTracker(binding)

        local tracker = {
            Destroyed = false,
            Character = character,
            Humanoid = humanoid,
            Root = root,
            Animator = animator,
            M1ing = character:FindFirstChild("M1ing", true) ~= nil,
            InsideLast = false,
            ActiveIds = {},
            TrackIds = setmetatable({}, {__mode = "k"}),
            TrackConnections = setmetatable({}, {__mode = "k"}),
            Connections = {}
        }

        binding.Tracker = tracker

        tracker.Connections[#tracker.Connections + 1] = animator.AnimationPlayed:Connect(function(track)
            if self.Destroyed or not self.Enabled or tracker.Destroyed then return end
            self:_registerTrack(player, tracker, track, true)
        end)

        tracker.Connections[#tracker.Connections + 1] = character.DescendantAdded:Connect(function(instance)
            if tracker.Destroyed or instance.Name ~= "M1ing" then return end
            tracker.M1ing = true
            tracker.InsideLast = false
            self.DebugInfo.M1Events = self.DebugInfo.M1Events + 1
            self:_handleM1(player, tracker, "M1ing")
        end)

        tracker.Connections[#tracker.Connections + 1] = character.DescendantRemoving:Connect(function(instance)
            if tracker.Destroyed or instance.Name ~= "M1ing" then return end
            task.defer(function()
                if tracker.Destroyed or not tracker.Character.Parent then return end
                tracker.M1ing = tracker.Character:FindFirstChild("M1ing", true) ~= nil
                if not tracker.M1ing then tracker.InsideLast = false end
            end)
        end)

        local okTracks, tracks = pcall(animator.GetPlayingAnimationTracks, animator)
        if okTracks and type(tracks) == "table" then
            for _, track in ipairs(tracks) do
                self:_registerTrack(player, tracker, track, true)
            end
        end

        if tracker.M1ing then
            self:_handleM1(player, tracker, "M1ing existing")
        end
    end

    function self:_queueCharacter(player, binding, character)
        if not binding then return end

        binding.Generation = binding.Generation + 1
        local generation = binding.Generation
        binding.Character = character
        self:_destroyTracker(binding)

        if not character then return end

        task.spawn(function()
            local humanoid = character:FindFirstChildWhichIsA("Humanoid") or character:WaitForChild("Humanoid", 8)
            if self.Destroyed or not self.Enabled then return end
            if binding.Generation ~= generation or binding.Character ~= character or not humanoid then return end

            local root = character:FindFirstChild("HumanoidRootPart") or character:WaitForChild("HumanoidRootPart", 8)
            if self.Destroyed or not self.Enabled then return end
            if binding.Generation ~= generation or binding.Character ~= character or not root then return end

            local animator = humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 8)
            if self.Destroyed or not self.Enabled then return end
            if binding.Generation ~= generation or binding.Character ~= character or not animator then return end

            self:_attachTracker(player, binding, character, humanoid, root, animator)
            self:_refreshTrackedCount()
        end)
    end

    function self:_refreshTrackedCount()
        local count = 0
        for player, binding in pairs(self.PlayerBindings) do
            if player ~= LocalPlayer and binding and binding.Tracker and not binding.Tracker.Destroyed then
                count = count + 1
            end
        end
        self.DebugInfo.TrackedPlayers = count
    end

    function self:_bindPlayer(player)
        if not player or player == LocalPlayer or self.PlayerBindings[player] then return end

        local binding = {
            Player = player,
            Character = nil,
            Generation = 0,
            Tracker = nil,
            Connections = {}
        }
        self.PlayerBindings[player] = binding

        binding.Connections[#binding.Connections + 1] = player.CharacterAdded:Connect(function(character)
            self:_queueCharacter(player, binding, character)
        end)

        binding.Connections[#binding.Connections + 1] = player.CharacterRemoving:Connect(function(character)
            if binding.Character == character then
                binding.Generation = binding.Generation + 1
                binding.Character = nil
                self:_destroyTracker(binding)
                self:_refreshTrackedCount()
            end
        end)

        if player.Character then
            self:_queueCharacter(player, binding, player.Character)
        end
    end

    function self:_unbindPlayer(player)
        local binding = self.PlayerBindings[player]
        if not binding then return end

        self.PlayerBindings[player] = nil
        binding.Generation = binding.Generation + 1
        self:_destroyTracker(binding)
        disconnectAll(binding.Connections)
        self:_refreshTrackedCount()
    end

    function self:_unbindAllPlayers()
        local players = {}
        for player in pairs(self.PlayerBindings) do
            players[#players + 1] = player
        end
        for _, player in ipairs(players) do
            self:_unbindPlayer(player)
        end
        self.DebugInfo.TrackedPlayers = 0
    end

    function self:_spatialTick()
        if not self.Config.M1Block then return end

        local myRoot = self:_localRoot()
        if not myRoot then return end

        for player, binding in pairs(self.PlayerBindings) do
            local tracker = binding and binding.Tracker
            if tracker and self:_trackerReady(tracker) then
                local distance = (tracker.Root.Position - myRoot.Position).Magnitude
                local inside = distance <= self.Config.NormalRange and self:_insideDetectionBox(tracker.Root, myRoot)

                if inside and not tracker.InsideLast then
                    if tracker.M1ing then
                        self:_handleM1(player, tracker, "M1ing enter")
                    else
                        for animationId in pairs(normalToGroup) do
                            if (tracker.ActiveIds[animationId] or 0) > 0 then
                                self:_pressBlock(0.15, "m1", "M1 animation enter", player, tracker, animationId, distance)
                                break
                            end
                        end
                    end
                end

                tracker.InsideLast = inside
            elseif tracker then
                tracker.InsideLast = false
            end
        end
    end

    function self:_onLocalCharacterRemoving()
        self.CharacterToken = self.CharacterToken + 1
        self.CounterToken = self.CounterToken + 1
        self:_releaseBlock("character removing")
        self:_destroyDetectionBox()
        self.DebugInfo.Character = "respawning"
        self.DebugInfo.Remote = "missing"
    end

    function self:_onLocalCharacterAdded(character)
        self.CharacterToken = self.CharacterToken + 1
        self.CounterToken = self.CounterToken + 1
        local token = self.CharacterToken

        self:_releaseBlock("character changed")
        self:_destroyDetectionBox()

        self.DebugInfo.Character = character and character.Name or "none"
        self.DebugInfo.Remote = "waiting"

        if not character then return end

        task.spawn(function()
            local root = character:FindFirstChild("HumanoidRootPart") or character:WaitForChild("HumanoidRootPart", 8)
            if self.Destroyed or not self.Enabled or token ~= self.CharacterToken then return end
            if LocalPlayer.Character ~= character or not root then return end

            local remote = character:FindFirstChild("Communicate") or character:WaitForChild("Communicate", 8)
            if self.Destroyed or not self.Enabled or token ~= self.CharacterToken then return end

            self.DebugInfo.Remote = remote and remote:IsA("RemoteEvent") and "ready" or "missing"
            if self.Config.M1Block then
                self:_ensureDetectionBox()
            end
        end)
    end

    function self:_heartbeat(dt)
        if self.Destroyed or not self.Enabled then return end

        local character = self:_localCharacter()
        local remote = character and character:FindFirstChild("Communicate")
        local live = Workspace:FindFirstChild("Live")

        self.DebugInfo.Character = character and character.Name or "none"
        self.DebugInfo.Remote = remote and remote:IsA("RemoteEvent") and "ready" or "missing"
        self.DebugInfo.Live = live and "ready" or "missing"
        self.DebugInfo.ScanHz = self.Config.ScanHz

        if self.Config.M1Block and character and character:FindFirstChild("HumanoidRootPart") then
            self:_ensureDetectionBox()
        elseif not self.Config.M1Block then
            self:_destroyDetectionBox()
        end

        if self.BlockActive and os_clock() >= self.BlockUntil then
            self:_releaseBlock("timeout")
        end

        self.ScanAccumulator = self.ScanAccumulator + (tonumber(dt) or 0)
        local interval = 1 / self.Config.ScanHz
        if self.ScanAccumulator >= interval then
            self.ScanAccumulator = self.ScanAccumulator % interval
            self:_spatialTick()
            self:_refreshTrackedCount()
        end
    end

    function self:ResetCombatState(reason)
        self.CounterToken = self.CounterToken + 1
        self.CounterPending = false
        self:_releaseBlock(reason or "manual reset")
        self.BlockUntil = 0
        self.BlockSource = nil
        self.BlockTargetPlayer = nil
        self.BlockTargetTracker = nil
        self:_restoreCamera()

        for _, binding in pairs(self.PlayerBindings) do
            local tracker = binding and binding.Tracker
            if tracker then
                tracker.InsideLast = false
            end
        end

        return true
    end

    function self:SetM1Block(value)
        self.Config.M1Block = value == true
        if not self.Config.M1Block then
            self:_destroyDetectionBox()
            if self.BlockActive and self.BlockSource == "m1" then
                self:_releaseBlock("M1 Block disabled")
            end
        elseif self.Enabled then
            self:_ensureDetectionBox()
        end
        return true
    end

    function self:SetM1AfterBlock(value)
        self.Config.M1AfterBlock = value == true
        if not self.Config.M1AfterBlock then
            self.CounterPending = false
            self.CounterToken = self.CounterToken + 1
        end
        return true
    end

    function self:SetFaceAttacker(value)
        self.Config.FaceAttacker = value == true
        if not self.Config.FaceAttacker then
            self:_restoreCamera()
        elseif self.BlockActive and self.BlockTargetTracker then
            self:_beginCameraLock(self.BlockTargetPlayer, self.BlockTargetTracker)
        end
        return true
    end

    function self:SetDashBlock(value)
        self.Config.DashBlock = value == true
        if not self.Config.DashBlock and self.BlockActive and self.BlockSource == "dash" then
            self:_releaseBlock("Dash Block disabled")
        end
        return true
    end

    function self:SetSkillBlock(value)
        self.Config.SkillBlock = value == true
        if not self.Config.SkillBlock and self.BlockActive and self.BlockSource == "skill" then
            self:_releaseBlock("Skill Block disabled")
        end
        return true
    end

    function self:SetShowDetectionBox(value)
        self.Config.ShowDetectionBox = value == true
        if self.Config.M1Block and self.Enabled then
            self:_ensureDetectionBox()
        end
        return true
    end

    function self:SetDebug(value)
        self.Config.Debug = value == true
        return true
    end

    function self:SetNormalRange(value)
        value = tonumber(value)
        if not value then return false end
        self.Config.NormalRange = clamp(value, 2, 30)
        return true
    end

    function self:SetSpecialRange(value)
        value = tonumber(value)
        if not value then return false end
        self.Config.SpecialRange = clamp(value, 5, 80)
        return true
    end

    function self:SetSkillRange(value)
        value = tonumber(value)
        if not value then return false end
        self.Config.SkillRange = clamp(value, 5, 80)
        return true
    end

    function self:SetSkillHold(value)
        value = tonumber(value)
        if not value then return false end
        self.Config.SkillHold = clamp(value, 0.1, 2)
        return true
    end

    function self:SetDetectionBoxSize(value)
        value = tonumber(value)
        if not value then return false end
        self.Config.DetectionBoxSize = clamp(value, 2, 40)
        if self.Config.M1Block and self.Enabled then
            self:_ensureDetectionBox()
        end
        return true
    end

    function self:SetScanHz(value)
        value = tonumber(value)
        if not value then return false end
        self.Config.ScanHz = clamp(math_floor(value + 0.5), 10, 60)
        self.DebugInfo.ScanHz = self.Config.ScanHz
        return true
    end

    function self:GetDebugInfo()
        local output = {}
        for key, value in pairs(self.DebugInfo) do
            output[key] = value
        end
        output.Enabled = self.Enabled
        output.BlockActive = self.BlockActive
        output.BlockSource = self.BlockSource or "none"
        output.CameraLock = self.CameraLockActive
        output.CounterPending = self.CounterPending
        output.M1Block = self.Config.M1Block
        output.DashBlock = self.Config.DashBlock
        output.SkillBlock = self.Config.SkillBlock
        return output
    end

    function self:GetConfig()
        return {
            M1Block = self.Config.M1Block,
            M1AfterBlock = self.Config.M1AfterBlock,
            FaceAttacker = self.Config.FaceAttacker,
            DashBlock = self.Config.DashBlock,
            SkillBlock = self.Config.SkillBlock,
            ShowDetectionBox = self.Config.ShowDetectionBox,
            Debug = self.Config.Debug,
            NormalRange = self.Config.NormalRange,
            SpecialRange = self.Config.SpecialRange,
            SkillRange = self.Config.SkillRange,
            SkillHold = self.Config.SkillHold,
            DetectionBoxSize = self.Config.DetectionBoxSize,
            ScanHz = self.Config.ScanHz,
            CounterRange = self.Config.CounterRange
        }
    end

    function self:Enable()
        if self.Destroyed or not LocalPlayer then return false end
        if self.Enabled then return true end

        self.Enabled = true
        self.DebugInfo.Runtime = "running"
        self.ScanAccumulator = 0
        self:ResetCombatState("runtime started")

        self.Connections[#self.Connections + 1] = LocalPlayer.CharacterAdded:Connect(function(character)
            self:_onLocalCharacterAdded(character)
        end)

        self.Connections[#self.Connections + 1] = LocalPlayer.CharacterRemoving:Connect(function()
            self:_onLocalCharacterRemoving()
        end)

        self.Connections[#self.Connections + 1] = Players.PlayerAdded:Connect(function(player)
            self:_bindPlayer(player)
        end)

        self.Connections[#self.Connections + 1] = Players.PlayerRemoving:Connect(function(player)
            self:_unbindPlayer(player)
        end)

        self.Connections[#self.Connections + 1] = RunService.Heartbeat:Connect(function(dt)
            local ok, err = pcall(self._heartbeat, self, dt)
            if not ok then self:_setError(err) end
        end)

        local okBind, errBind = pcall(function()
            RunService:BindToRenderStep(self.RenderStepName, Enum.RenderPriority.Camera.Value + 1, function()
                local ok, err = pcall(self._updateCameraLock, self)
                if not ok then self:_setError(err) end
            end)
        end)
        if okBind then
            self.RenderBound = true
        else
            self:_setError(errBind)
        end

        for _, player in ipairs(Players:GetPlayers()) do
            self:_bindPlayer(player)
        end

        if LocalPlayer.Character then
            self:_onLocalCharacterAdded(LocalPlayer.Character)
        end

        return true
    end

    function self:Disable()
        if self.Destroyed then return false end
        if not self.Enabled then return true end

        self.Enabled = false
        self.DebugInfo.Runtime = "idle"
        self.CharacterToken = self.CharacterToken + 1
        self.CounterToken = self.CounterToken + 1

        disconnectAll(self.Connections)
        self:_unbindAllPlayers()

        if self.RenderBound then
            pcall(RunService.UnbindFromRenderStep, RunService, self.RenderStepName)
            self.RenderBound = false
        end

        self.CounterPending = false
        self:_releaseBlock("runtime stopped")
        self:_restoreCamera()
        self:_destroyDetectionBox()
        self.ScanAccumulator = 0

        self:_communicate("LeftClickRelease", true)
        return true
    end

    function self:Destroy()
        if self.Destroyed then return end
        self:Disable()
        self.Destroyed = true
        self.DebugInfo.Runtime = "destroyed"
        self.PlayerBindings = nil
    end

    return self
end

return Factory

]],
    ["src/games/features/volleyball/actions.lua"] = [[
-- Volleyball 4.2 - PlayerAction / animacoes. Mapa dos remotes e animacoes que o
-- jogo usa para cada acao de quadra, levantado a partir do script local do
-- proprio jogo. Este modulo NAO liga nada sozinho: so publica as acoes para as
-- automacoes do backend (spawn da bola, set, spike, block, bump, dive, serve)
-- usarem o caminho REAL do jogo -- FireServer no PlayerAction e LoadAnimation no
-- Animator -- em vez de fingir o movimento.
--
-- Contrato do jogo (por observacao, pode mudar em patches):
--   PlayerAction = ReplicatedStorage.Remotes.PlayerAction  (RemoteEvent)
--   Animations   = ReplicatedStorage.Assets.Animations
--   PlayerData_m = require(ReplicatedStorage.PlayerData)   (indice das animacoes
--                  equipadas pelo jogador em PlayerData_m.Animations)
--
-- Nomes exatos dos argumentos passados ao FireServer:
--   Set frontal  -> "Setting"
--   Set de costas-> "Backsetting"
--   Spike        -> "Spiking"
--   Block        -> "Blocking"
--   SpawnBall    -> "SpawnBall", "Spawn"
--   Serve        -> "SpawnBall", "Serve"  e depois "Serving"
-- Bump e Dive NAO firem remote: so tocam a animacao (recepcao/mergulho).
--
-- Direcao do set: frontal = animacao Set[.Set][Front]; costas = [Back]. A tabela
-- de indice real vem de PlayerData.Animations.Set (o jogador pode estar com um
-- pack diferente), entao o modulo le esse indice em runtime em vez de fixar um
-- numero -- e cai no indice 1 se nao achar.

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Actions = {}

Actions.RemotePath = {"Remotes", "PlayerAction"}
Actions.AnimationsPath = {"Assets", "Animations"}
Actions.PlayerDataPath = "PlayerData"
Actions.ServeHitDelay = 1.2 -- segundos entre "SpawnBall/Serve" e "Serving" (igual ao script do jogo)

-- resolve lazily, sem WaitForChild bloqueante (regra do repo)
local function childPath(root, path)
    local node = root
    for _, name in ipairs(path) do
        node = node and node:FindFirstChild(name)
    end
    return node
end

function Actions.GetRemote()
    return childPath(ReplicatedStorage, Actions.RemotePath)
end

function Actions.GetAnimations()
    return childPath(ReplicatedStorage, Actions.AnimationsPath)
end

-- require do PlayerData protegido: em alguns lugares ele nao esta carregado
-- ainda e um erro derrubaria o backend inteiro.
function Actions.GetPlayerData()
    local module = ReplicatedStorage:FindFirstChild(Actions.PlayerDataPath)
    if not module then return nil end
    local ok, data = pcall(require, module)
    if not ok or type(data) ~= "table" then return nil end
    return data
end

function Actions.GetAnimator()
    local player = game:GetService("Players").LocalPlayer
    local character = player and player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    return humanoid and humanoid:FindFirstChildOfClass("Animator")
end

-- Le o indice de animacao do jogador; sem PlayerData cai no indice default.
local function animationIndex(data, kind, fallback)
    local animations = data and data.Animations
    local value = animations and animations[kind]
    if type(value) == "number" or type(value) == "string" then return value end
    return fallback
end

-- Navega Animations.<kind>.<index>[.<dir>] com os fallbacks documentados.
local function resolveAnimation(kind, dir, indexFallback)
    local animations = Actions.GetAnimations()
    if not animations then return nil end
    local node = animations:FindFirstChild(kind)
    if not node then return nil end

    local index = animationIndex(Actions.GetPlayerData(), kind, indexFallback)
    local indexed = node:FindFirstChild(tostring(index))
    local target = indexed or node

    if dir then
        return target:FindFirstChild(dir) or target
    end
    return target
end

local function fire(actor, ...)
    local remote = Actions.GetRemote()
    if not remote then return false, "PlayerAction remote ausente" end
    local ok, err = pcall(remote.FireServer, remote, ...)
    if not ok then return false, tostring(err) end
    local log = actor and actor.Log
    if log then log.Actions = log.Actions + 1 end
    return true
end

-- Toca uma animacao no Animator. Devolve a track (ou nil se nao achou/animator
-- ausente). Nao e fatal: a acao remota ainda dispara sem a animacao.
local function play(actor, kind, dir, indexFallback)
    local animator = Actions.GetAnimator()
    if not animator then return nil end
    local animation = resolveAnimation(kind, dir, indexFallback)
    if not animation then return nil end
    local ok, track = pcall(animator.LoadAnimation, animator, animation)
    if not ok or not track then return nil end
    pcall(track.Play, track)
    actor.Playing = track
    actor.LastAnimation = kind
    return track
end

-- === ACOES === (espelham exatamente as funcoes do script do jogo)

-- Set frontal (bloqueio de frente) ou de costas. frontal=true -> Front/Setting.
function Actions.Set(actor, frontal)
    local isFront = frontal ~= false
    play(actor, "Set", isFront and "Front" or "Back", 1)
    return fire(actor, isFront and "Setting" or "Backsetting")
end

function Actions.Spike(actor)
    play(actor, "Spike", "Spike", 1)
    return fire(actor, "Spiking")
end

function Actions.Block(actor)
    play(actor, "Block", nil, 1)
    return fire(actor, "Blocking")
end

-- Bump (recepcao): so animacao, sem remote.
function Actions.Bump(actor)
    play(actor, "Receive", nil, 1)
    return true
end

-- Dive (mergulho): so animacao, sem remote.
function Actions.Dive(actor)
    play(actor, "Dive", nil, 1)
    return true
end

function Actions.SpawnBall(actor)
    return fire(actor, "SpawnBall", "Spawn")
end

-- Serve: spawna a bola de saque, espera o delay do jogo e fire "Serving" com a
-- animacao de hit. Assincrono por causa do wait, por isso roda em task.spawn e
-- guarda a task no ator para o Destroy poder cancelar.
function Actions.Serve(actor)
    local started, err = fire(actor, "SpawnBall", "Serve")
    if not started then return false, err end
    actor.Serving = true
    actor.ServeTask = task.spawn(function()
        task.wait(Actions.ServeHitDelay)
        if actor.Destroyed or not actor.Serving then return end
        play(actor, "Serve", "Hit", 1)
        fire(actor, "Serving")
    end)
    return true
end

function Actions.Cancel(actor)
    actor.Serving = false
    if actor.ServeTask then
        pcall(task.cancel, actor.ServeTask)
        actor.ServeTask = nil
    end
end

-- Diagnostico: o que existe de fato no jogo, para o Debug tab. Nao muda estado.
function Actions.Inspect()
    local data = Actions.GetPlayerData()
    return {
        Remote = Actions.GetRemote() ~= nil,
        Animations = Actions.GetAnimations() ~= nil,
        PlayerData = data ~= nil,
        Animator = Actions.GetAnimator() ~= nil,
        SetIndex = animationIndex(data, "Set", 1),
    }
end

return Actions

]],
    ["src/games/features/volleyball/jump-anywhere.lua"] = [[
-- Volleyball 4.2 - Jump Anywhere + impulso extra. Um unico recurso, um unico
-- toggle: liga as DUAS coisas juntas --
--   1) IMPULSO EXTRA: quando o jogador pula de fato, no frame seguinte
--      multiplica AssemblyLinearVelocity.Y por (1 + Aumento/100). Este e o
--      recurso PRINCIPAL e o unico que depende so do proprio personagem
--      (Humanoid) -- nao precisa de modulo nenhum do jogo.
--   2) JUMP BYPASS (best-effort): procura o modulo CharacterActions do jogo e
--      patcheia o upvalue de checagem de pulo para que "NoJump" (o veto) vire
--      nil. Se o modulo nao existir / o executor nao tiver debug.getupvalue, o
--      bypass apenas nao entra -- o IMPULSO continua funcionando com o Humanoid.
--
-- Historico do bug: antes, o impulso rodava dentro de um heartbeat que exigia
-- `self.CA` (o CharacterActions). Como o CA so era gravado quando o patch do
-- upvalue dava certo -- e neste jogo o caminho do modulo nem batia -- o CA ficava
-- nil e o impulso NUNCA rodava. O log do usuario provava: "CharacterActions
-- indisponivel" e depois "bypass". Agora o impulso nao depende disso.
--
-- O gatilho do impulso e o EVENTO do Humanoid (`Jumping`) e, como reserva, a
-- transicao para o ar (FloorMaterial/GetState) com velocidade vertical subindo.
-- O flag CA.State.Jumped fica como terceiro gatilho. Um cooldown curto evita
-- aplicar duas vezes o mesmo pulo.
--
-- Sem UI aqui: quem monta o toggle/slider e o backend (viz. volleyball42.lua).
-- O modulo so publica new/Start/Stop/SetImpulse/Destroy.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local workspaceService = game:GetService("Workspace")

local Visual = {}
Visual.__index = Visual

Visual.Id = "DepHub_JumpAnywhere"
-- Caminho preferido do modulo do jogo que guarda as acoes do personagem. E um
-- ModuleScript dentro de um Folder cujo nome e o do dev do mapa. Se esse caminho
-- mudar (o dev renomeia a pasta), resolveCharacterActions cai pra busca recursiva
-- por nome no Workspace.
Visual.ScriptPath = {"guilhermealone1", "CharacterScript", "CharacterActions"}
Visual.ScriptName = "CharacterActions"
-- Indice PREFERIDO do upvalue de checagem dentro de CA.Jump. Nao e o unico: se
-- o upvalue desse indice nao for a funcao de check, findCheckUpvalue procura uma
-- funcao cujo nome contenha "check" e, na falta dela, a primeira funcao. O script
-- do jogo nao exporta o nome, entao confiar so no indice quebrava num build novo.
Visual.CheckUpvalue = 3
-- Re-tenta achar o CharacterActions / aplicar o patch a cada N frames enquanto
-- faltar um dos dois (o hub sobe na hora; o modulo do jogo pode vir depois).
Visual.ResolveRetryFrames = 30
-- Frames de re-tentativa do impulso quando a velocidade do pulo ainda nao foi
-- escrita pela fisica. Curto de proposito: cobre a corrida sem empilhar boost.
Visual.ImpulseRetryFrames = 4
-- Frames minimos entre dois impulsos. Vários gatilhos podem ver o mesmo pulo.
Visual.ImpulseCooldownFrames = 3

local function childPath(root, path)
    local node = root
    for _, name in ipairs(path) do
        node = node and node:FindFirstChild(name)
    end
    return node
end

local function resolveCharacterActions()
    local module = childPath(workspaceService, Visual.ScriptPath)
    if not module then
        -- O caminho fixo pode ter mudado, ou o modulo pode morar fora do
        -- Workspace (ReplicatedStorage e o lugar comum para um ModuleScript de
        -- cliente). Procura pelo nome, recursivamente, nos dois.
        for _, root in ipairs({workspaceService, ReplicatedStorage}) do
            local ok, found = pcall(function()
                return root:FindFirstChild(Visual.ScriptName, true)
            end)
            if ok and found then module = found; break end
        end
    end
    if not module then return nil end
    local ok, data = pcall(require, module)
    if not ok or type(data) ~= "table" then return nil end
    return data
end

local function getDebug()
    local env = type(getgenv) == "function" and getgenv() or _G
    local library = env.debug or debug
    if type(library) ~= "table" then return nil end
    if type(library.getupvalue) ~= "function" or type(library.setupvalue) ~= "function" then return nil end
    return library
end

-- Le um upvalue por indice tolerando as duas assinaturas de getupvalue que
-- circulam nos executores: (indice) -> nome, valor  OU  (indice) -> valor.
local function readUpvalue(library, fn, index)
    local ok, a, b = pcall(library.getupvalue, fn, index)
    if not ok then return nil, nil end
    if type(a) == "string" then return a, b end
    return nil, a
end

local function writeUpvalue(library, fn, index, value)
    local ok = pcall(library.setupvalue, fn, index, value)
    if not ok then return false end
    local _, current = readUpvalue(library, fn, index)
    return current == value
end

-- Acha o upvalue que guarda a checagem de pulo. Prefere o indice conhecido; se
-- ele nao for funcao, procura um nome com "check"; por ultimo aceita a primeira
-- funcao. Devolve indice, valor (ou nil).
local function findCheckUpvalue(library, fn, preferred)
    local firstFunction
    for index = 1, 64 do
        local name, value = readUpvalue(library, fn, index)
        if value == nil then break end
        if type(value) == "function" then
            if index == preferred then return index, value end
            if not firstFunction then firstFunction = {index, value} end
            if type(name) == "string" and name:lower():find("check", 1, true) then
                return index, value
            end
        end
    end
    if firstFunction then return firstFunction[1], firstFunction[2] end
    return nil, nil
end

-- O flag de pulo do jogo virou "true" neste frame? Aceita booleano (o caso
-- documentado) e numero (um contador que sobe).
local function jumpStarted(current, previous)
    if type(current) == "number" then
        return current > (tonumber(previous) or 0)
    end
    return current == true and previous ~= true
end

-- O Humanoid do personagem atual, ou nil.
local function currentHumanoid()
    local player = Players.LocalPlayer
    local character = player and player.Character
    if not character then return nil end
    return character:FindFirstChildOfClass("Humanoid")
end

-- O personagem esta no ar? Devolve true/false, ou nil quando nao da pra saber
-- (executor/sandbox sem FloorMaterial e sem GetState). nil significa "nao usa
-- este sinal".
local function isAirborne(humanoid)
    local floor = humanoid.FloorMaterial
    if floor ~= nil then
        return floor == Enum.Material.Air
    end
    local ok, state = pcall(humanoid.GetState, humanoid)
    if ok then
        return state == Enum.HumanoidStateType.Jumping
            or state == Enum.HumanoidStateType.Freefall
    end
    return nil
end

function Visual.new()
    local self = setmetatable({}, Visual)
    self.Active = false
    self.Impulse = 0          -- 0..150 (%)
    self.BypassReady = false  -- o patch de upvalue esta aplicado?
    self.BypassError = nil
    self.CA = nil             -- CharacterActions do jogo (opcional)
    self.CheckIndex = nil     -- indice do upvalue que patchamos
    self.Original = nil
    self.Patched = nil
    self.Connections = {}
    self.HumanoidConnections = {}
    self.Humanoid = nil
    self.WasAirborne = false
    self.PreviousJumped = false
    self.ResolveCountdown = 0
    self.ImpulseCooldown = 0
    return self
end

-- Aplica o patch do upvalue de check. Devolve true se ficou aplicado.
--
-- O CA e gravado SEMPRE que for encontrado, ANTES de exigir o debug: o impulso
-- nao depende do patch. So o patch exige a primitiva.
function Visual:_applyBypass()
    if self.BypassReady then return true end
    local library = getDebug()
    if not library then return false, "debug.getupvalue/setupvalue ausente no executor" end
    local ca = self.CA
    if not ca then return false, "CharacterActions indisponivel" end
    if type(ca.Jump) ~= "function" then return false, "CA.Jump ausente" end
    if type(ca.State) ~= "table" then return false, "CA.State ausente" end

    local index, original = findCheckUpvalue(library, ca.Jump, Visual.CheckUpvalue)
    if type(original) ~= "function" then
        return false, "nenhum upvalue de funcao em CA.Jump"
    end

    -- "NoJump" e o veto do jogo: devolver nil equivale a "pode pular". Para
    -- qualquer outro retorno, o wrapper e um repasse identico -- patchar o
    -- upvalue errado nao muda comportamento nenhum.
    local patched = function(...)
        local result = original(...)
        if result == "NoJump" then return nil end
        return result
    end

    if not writeUpvalue(library, ca.Jump, index, patched) then
        return false, "falha ao escrever o upvalue"
    end

    self.CheckIndex = index
    self.Original = original
    self.Patched = patched
    self.BypassReady = true
    return true
end

function Visual:_restoreBypass()
    if not self.BypassReady or not self.CA then return end
    local library = getDebug()
    if library and self.CheckIndex then
        local _, current = readUpvalue(library, self.CA.Jump, self.CheckIndex)
        -- So restaura se o upvalue ainda for o NOSSO patch (outro script pode
        -- ter patcheado depois; nao desfazemos o trabalho alheio as cegas).
        if current == self.Patched then
            writeUpvalue(library, self.CA.Jump, self.CheckIndex, self.Original)
        end
    end
    self.BypassReady = false
    self.CheckIndex = nil
    self.Original = nil
    self.Patched = nil
end

-- Tenta resolver o CA e aplicar o patch. Nunca derruba nada: guarda o motivo em
-- BypassError. O impulso nao depende do resultado.
function Visual:_arm()
    if not self.CA then
        local ca = resolveCharacterActions()
        if type(ca) == "table" then self.CA = ca end
    end
    if not self.CA then
        self.BypassError = "CharacterActions indisponivel"
        return false
    end
    if not self.BypassReady then
        local ok, err = self:_applyBypass()
        if not ok then self.BypassError = err end
    end
    return self.BypassReady
end

-- Liga/religa os eventos do Humanoid atual (Jumping/StateChanged). Re-chamado
-- todo frame para acompanhar respawn (o Humanoid muda).
function Visual:_watchHumanoid()
    local humanoid = currentHumanoid()
    if humanoid == self.Humanoid then return end

    for _, connection in ipairs(self.HumanoidConnections) do
        pcall(function() connection:Disconnect() end)
    end
    self.HumanoidConnections = {}
    self.Humanoid = humanoid
    self.WasAirborne = false
    if not humanoid then return end

    -- `Jumping` e o sinal ideal: dispara no inicio do pulo. Em sandbox/executor
    -- que nao exponha o sinal, o pcall apenas falha e o gatilho de estado cobre.
    pcall(function()
        local connection = humanoid.Jumping:Connect(function()
            self:_queueImpulse()
        end)
        self.HumanoidConnections[#self.HumanoidConnections + 1] = connection
    end)
    pcall(function()
        local connection = humanoid.StateChanged:Connect(function(_, newState)
            if newState == Enum.HumanoidStateType.Jumping
                or newState == Enum.HumanoidStateType.Freefall then
                self:_queueImpulse()
            end
        end)
        self.HumanoidConnections[#self.HumanoidConnections + 1] = connection
    end)
end

-- Pede um impulso para o proximo frame, respeitando o cooldown. Pode ser
-- chamado por varios gatilhos vendo o mesmo pulo.
function Visual:_queueImpulse()
    if not self.Active or self.Impulse <= 0 then return end
    if self.ImpulseCooldown > 0 then return end
    self.ImpulseCooldown = Visual.ImpulseCooldownFrames
    -- Aplica um frame depois: a velocidade do pulo so esta posta no frame
    -- seguinte, igual ao script de referencia. Se ela ainda nao estiver (corrida
    -- com a fisica), re-tenta por alguns frames -- sem NUNCA inventar um pulo
    -- para um personagem parado no chao.
    task.spawn(function()
        for _ = 1, Visual.ImpulseRetryFrames do
            RunService.Heartbeat:Wait()
            if not self.Active then return end
            if self:_applyImpulse() then return end
        end
    end)
end

-- Multiplica a velocidade vertical REAL do pulo pelo impulso. Devolve true
-- quando nao ha mais o que tentar (aplicou, ou nao ha alvo). Devolve false
-- apenas quando o personagem ainda nao esta subindo -- o chamador re-tenta.
function Visual:_applyImpulse()
    if not self.Active then return true end
    if self.Impulse <= 0 then return true end

    local player = Players.LocalPlayer
    local character = player and player.Character
    if not character then return true end
    local hrp = character:FindFirstChild("HumanoidRootPart")
    if not hrp then return true end

    local velocity = hrp.AssemblyLinearVelocity
    if type(velocity) ~= "table" and type(velocity) ~= "userdata" then return true end
    -- So impulsa um PULO em subida. Velocidade negativa e queda de borda;
    -- zero e personagem parado (o pulo ainda nao foi escrito). Nos dois casos
    -- nao ha impulso a dar -- e nunca transformamos um deles em salto.
    if velocity.Y <= 0 then return false end

    local multiplier = 1 + self.Impulse / 100
    hrp.AssemblyLinearVelocity = Vector3.new(
        velocity.X,
        velocity.Y * multiplier,
        velocity.Z
    )
    return true
end

function Visual:Start()
    if self.Active then return false end
    self.Active = true
    self.PreviousJumped = false
    self.ImpulseCooldown = 0
    self.ResolveCountdown = 0
    self.WasAirborne = false

    -- Resolve o CA e tenta o patch (best-effort). O resultado e o que o backend
    -- usa pra avisar no toggle; o IMPULSO nao depende dele.
    self:_arm()
    local bypassOk = self.BypassReady
    local bypassErr = (not bypassOk) and (self.BypassError or "bypass") or nil

    -- Liga o Humanoid atual de imediato (se ja existir).
    self:_watchHumanoid()

    local connection = RunService.Heartbeat:Connect(function()
        if not self.Active then return end

        -- Retry do bypass/CA enquanto faltar um dos dois.
        if not self.CA or not self.BypassReady then
            self.ResolveCountdown = (self.ResolveCountdown or 0) - 1
            if self.ResolveCountdown <= 0 then
                self.ResolveCountdown = Visual.ResolveRetryFrames
                self:_arm()
            end
        end

        if self.ImpulseCooldown > 0 then
            self.ImpulseCooldown = self.ImpulseCooldown - 1
        end

        -- Acompanha respawn e liga os eventos do Humanoid atual.
        self:_watchHumanoid()

        -- Gatilho de RESERVA: subiu para o ar com velocidade positiva. Cobre
        -- executor/sandbox onde o sinal `Jumping` nao chega.
        local humanoid = self.Humanoid
        if humanoid then
            local airborne = isAirborne(humanoid)
            if airborne ~= nil then
                local player = Players.LocalPlayer
                local character = player and player.Character
                local hrp = character and character:FindFirstChild("HumanoidRootPart")
                local rising = hrp and hrp.AssemblyLinearVelocity.Y > 1
                if airborne and not self.WasAirborne and rising then
                    self:_queueImpulse()
                end
                self.WasAirborne = airborne
            end
        end

        -- Gatilho terciario: o flag do CharacterActions, quando existir.
        local ca = self.CA
        if ca then
            local jumped = ca.State and ca.State.Jumped
            if jumpStarted(jumped, self.PreviousJumped) then
                self:_queueImpulse()
            end
            self.PreviousJumped = jumped
        end
    end)
    self.Connections[#self.Connections + 1] = connection

    return bypassOk, bypassErr
end

function Visual:Stop()
    if not self.Active and not self.BypassReady then return end
    self.Active = false
    self.PreviousJumped = false
    self.ImpulseCooldown = 0
    self.WasAirborne = false

    for _, connection in ipairs(self.Connections) do
        pcall(function() connection:Disconnect() end)
    end
    self.Connections = {}

    for _, connection in ipairs(self.HumanoidConnections) do
        pcall(function() connection:Disconnect() end)
    end
    self.HumanoidConnections = {}
    self.Humanoid = nil

    self:_restoreBypass()
    return true
end

-- Impulso em % (0-150). 0 = so o bypass, pulo original.
function Visual:SetImpulse(percent)
    if type(percent) ~= "number" then return false end
    self.Impulse = math.clamp(math.floor(percent + 0.5), 0, 150)
    return true
end

function Visual:Destroy()
    self:Stop()
    self.CA = nil
    return true
end

return Visual

]],
    ["src/games/mm2.lua"] = [[
local game=game
local type=type
local tostring=tostring
local tonumber=tonumber
local pcall=pcall
local pairs=pairs

local Players=game:GetService("Players")
local Workspace=game:GetService("Workspace")
local LocalPlayer=Players.LocalPlayer
local env=type(getgenv)=="function" and getgenv() or _G
local STATE_KEY="__DEPHUB_MM2"
local BASE_URL=((type(getgenv)=="function" and getgenv() or _G).__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"
local VERSION="0.0.5"

local previous=type(env[STATE_KEY])=="table" and env[STATE_KEY] or nil
if previous and type(previous.Destroy)=="function" then pcall(previous.Destroy,previous) end

local function loadFeature(path,context)
    local cb=tostring((env.__DEPHUB or {}).SourceCacheBust or "")
    local okGet,source=pcall(function() return __dephubHttpGet(BASE_URL..path..(cb~="" and ("?cb="..cb) or "")) end)
    if not okGet or type(source)~="string" or #source==0 then return false,tostring(source) end
    local okCompile,chunk,err=pcall(loadstring,source)
    if not okCompile or type(chunk)~="function" then return false,tostring(err or chunk) end
    local okRun,factory=pcall(chunk)
    if not okRun or type(factory)~="table" or type(factory.new)~="function" then return false,tostring(factory) end
    local okNew,feature=pcall(factory.new,context)
    if not okNew or type(feature)~="table" then return false,tostring(feature) end
    return true,feature
end

local base={Players=Players,Workspace=Workspace,LocalPlayer=LocalPlayer}
local okRole,RoleTracker=loadFeature("src/games/features/mm2/roletracker.lua",base)
if not okRole then return false end
base.RoleTracker=RoleTracker
local okRound,RoundTracker=loadFeature("src/games/features/mm2/roundtracker.lua",base)
if not okRound then pcall(RoleTracker.Destroy,RoleTracker) return false end
base.RoundTracker=RoundTracker
local okESP,ESP=loadFeature("src/games/features/mm2/esp.lua",base)
if not okESP then pcall(RoleTracker.Destroy,RoleTracker) pcall(RoundTracker.Destroy,RoundTracker) return false end
local okCoin,CoinFarm=loadFeature("src/games/features/mm2/coinfarm.lua",base)
if not okCoin then pcall(RoleTracker.Destroy,RoleTracker) pcall(RoundTracker.Destroy,RoundTracker) pcall(ESP.Destroy,ESP) return false end
local okTeleport,PlayerTeleport=loadFeature("src/games/features/mm2/playerteleport.lua",base)
if not okTeleport then pcall(RoleTracker.Destroy,RoleTracker) pcall(RoundTracker.Destroy,RoundTracker) pcall(ESP.Destroy,ESP) pcall(CoinFarm.Destroy,CoinFarm) return false end
local okGun,GunDrop=loadFeature("src/games/features/mm2/gundrop.lua",base)
if not okGun then pcall(RoleTracker.Destroy,RoleTracker) pcall(RoundTracker.Destroy,RoundTracker) pcall(ESP.Destroy,ESP) pcall(CoinFarm.Destroy,CoinFarm) pcall(PlayerTeleport.Destroy,PlayerTeleport) return false end

local State={
    Version=VERSION,
    Started=false,
    Destroyed=false,
    Features={RoleTracker=RoleTracker,RoundTracker=RoundTracker,ESP=ESP,CoinFarm=CoinFarm,PlayerTeleport=PlayerTeleport,GunDrop=GunDrop},
    Toggles={RoleESP=false,AutoCoins=false,GunDropESP=false,AutoGetGun=false},
    Values={CoinSafeDistance=18,CoinDelay=0.05,GunSafeDistance=22,GunPickupHold=0.16}
}

env[STATE_KEY]=State
env.__DEPHUB=env.__DEPHUB or {}
env.__DEPHUB.MM2=State

function State:SetRoleESP(v)
    v=v==true
    self.Toggles.RoleESP=v
    return (v and ESP:Enable() or ESP:Disable())~=false
end

function State:SetAutoCoins(v)
    v=v==true
    self.Toggles.AutoCoins=v
    return (v and CoinFarm:Enable() or CoinFarm:Disable())~=false
end

function State:SetCoinSafeDistance(v)
    v=tonumber(v)
    if not v then return false end
    if not CoinFarm:SetSafeDistance(v) then return false end
    self.Values.CoinSafeDistance=CoinFarm.SafeDistance
    return true
end

function State:SetCoinDelay(v)
    v=tonumber(v)
    if not v then return false end
    if not CoinFarm:SetDelay(v) then return false end
    self.Values.CoinDelay=CoinFarm.Delay
    return true
end

function State:SetGunDropESP(v)
    v=v==true
    if GunDrop:SetESP(v)==false then return false end
    self.Toggles.GunDropESP=v
    return true
end

function State:SetAutoGetGun(v)
    v=v==true
    if GunDrop:SetAutoPickup(v)==false then return false end
    self.Toggles.AutoGetGun=v
    return true
end

function State:SetGunSafeDistance(v)
    v=tonumber(v)
    if not v or GunDrop:SetSafeDistance(v)==false then return false end
    self.Values.GunSafeDistance=GunDrop.SafeDistance
    return true
end

function State:SetGunPickupHold(v)
    v=tonumber(v)
    if not v or GunDrop:SetPickupHold(v)==false then return false end
    self.Values.GunPickupHold=GunDrop.PickupHold
    return true
end

function State:TeleportNextAlivePlayer()
    if self.Destroyed then return false,"destroyed" end
    return PlayerTeleport:TeleportNext()
end

function State:GetAlivePlayers() return PlayerTeleport:GetAliveTargets() end
function State:GetGunDrop() return RoleTracker:GetGunDrop() end
function State:GetToggle(name) return self.Toggles[name]==true end
function State:GetValue(name) return self.Values[name] end
function State:GetMurder() return RoleTracker:GetMurder() end
function State:GetSheriff() return RoleTracker:GetSheriff() end
function State:IsRoundActive() return RoundTracker:IsRoundActive() end
function State:GetDebugInfo()
    return {
        Role=RoleTracker:GetDebugInfo(),
        Round=RoundTracker:GetDebugInfo(),
        Coin=CoinFarm:GetDebugInfo(),
        Teleport=PlayerTeleport:GetDebugInfo(),
        Gun=GunDrop:GetDebugInfo()
    }
end

function State:Start()
    if self.Destroyed or self.Started then return false end
    self.Started=true
    RoleTracker:Enable()
    RoundTracker:Enable()
    self.RoundConnection=RoundTracker:OnChanged(function(active)
        if not active then RoleTracker:ResetRound() end
    end)
    return true
end

function State:Destroy()
    if self.Destroyed then return end
    self.Destroyed=true
    if self.RoundConnection then pcall(self.RoundConnection.Disconnect,self.RoundConnection) self.RoundConnection=nil end
    for _,feature in pairs(self.Features or {}) do
        if type(feature)=="table" and type(feature.Destroy)=="function" then pcall(feature.Destroy,feature) end
    end
    self.Features=nil
    if env[STATE_KEY]==self then env[STATE_KEY]=nil end
    if env.__DEPHUB and env.__DEPHUB.MM2==self then env.__DEPHUB.MM2=nil end
end

if not LocalPlayer then return false end
if not State:Start() then State:Destroy() return false end

local UI=env.__DEPHUB and env.__DEPHUB.UI
do
    local Kit=env.__DEPHUB and env.__DEPHUB.UIKit
    if Kit then
        -- Roles are pure information on screen -> Visual.
        local roles=Kit.Section(Kit.Tab("Roles","Visual"),"Role ESP","Left")
        if roles then
            roles:CreateToggle("Show Murder and Sheriff",false,function(value)
                State:SetRoleESP(value)
            end)
            roles:CreateParagraph("Identification","Highlights the Murder in red and the Sheriff in blue.")
        end

        -- Coin collection is a farm loop -> Farm.
        local coins=Kit.Section(Kit.Tab("Coin Farm","Farm"),"Collect coins","Left")
        if coins then
            -- Auto collect + the distance it keeps share a line; the interval is
            -- its own row.
            local coinRow=Kit.Row(coins)
            if coinRow then
                coinRow:CreateToggle("Auto collect",false,function(value)
                    State:SetAutoCoins(value)
                end)
                coinRow:CreateSlider("Safe distance",0,80,State.Values.CoinSafeDistance,function(value)
                    State:SetCoinSafeDistance(value)
                end)
            else
                coins:CreateToggle("Auto collect",false,function(value)
                    State:SetAutoCoins(value)
                end)
                coins:CreateSlider("Safe distance",0,80,State.Values.CoinSafeDistance,function(value)
                    State:SetCoinSafeDistance(value)
                end)
            end
            coins:CreateSlider("Interval (seconds)",0.02,0.3,State.Values.CoinDelay,function(value)
                State:SetCoinDelay(value)
            end)
        end

        -- Gun drop is a farm action with a visual ESP bit -> Farm.
        local gun=Kit.Section(Kit.Tab("Gun Drop","Farm"),"Dropped gun","Left")
        if gun then
            -- The two gun switches share a line, then the two value sliders, which
            -- pair with the feature each drives.
            local gunRow=Kit.Row(gun)
            if gunRow then
                gunRow:CreateToggle("Gun ESP",false,function(value)
                    State:SetGunDropESP(value)
                end)
                gunRow:CreateToggle("Auto pickup gun",false,function(value)
                    State:SetAutoGetGun(value)
                end)
            else
                gun:CreateToggle("Gun ESP",false,function(value)
                    State:SetGunDropESP(value)
                end)
                gun:CreateToggle("Auto pickup gun",false,function(value)
                    State:SetAutoGetGun(value)
                end)
            end
            local gunSliderRow=Kit.Row(gun)
            if gunSliderRow then
                gunSliderRow:CreateSlider("Safe distance from Murder",5,80,State.Values.GunSafeDistance,function(value)
                    State:SetGunSafeDistance(value)
                end)
                gunSliderRow:CreateSlider("Pickup hold time",0.05,0.5,State.Values.GunPickupHold,function(value)
                    State:SetGunPickupHold(value)
                end)
            else
                gun:CreateSlider("Safe distance from Murder",5,80,State.Values.GunSafeDistance,function(value)
                    State:SetGunSafeDistance(value)
                end)
                gun:CreateSlider("Pickup hold time",0.05,0.5,State.Values.GunPickupHold,function(value)
                    State:SetGunPickupHold(value)
                end)
            end
        end

        -- Teleport-to-player is a movement/player action -> Movement.
        local players=Kit.Section(Kit.Tab("Players","Movement"),"Alive players","Left")
        if players then
            players:CreateButton("Teleport to next alive player",function()
                local ok,name=State:TeleportNextAlivePlayer()
                if type(UI.Notify)=="function" then
                    UI:Notify("MM2",ok and ("Teleported to "..tostring(name)) or tostring(name or "Could not teleport"),ok and "success" or "warning")
                end
            end)
            players:CreateParagraph("Status","Teleport cycles through the round's alive players.")
        end
    end
end

-- Report this backend's own structure and live state into the shared Debug tab.
-- Every probe names the exact instance a feature reads, so a game update that
-- renames or removes one shows up as [FALHA] at the point of failure.
do
    local Diag=env.__DEPHUB and env.__DEPHUB.Diagnostics
    if Diag and type(Diag.Probe)=="function" then
        Diag:SetEnvironment({["MM2 version"]=VERSION})
        for _,name in ipairs({"roletracker","roundtracker","esp","coinfarm","playerteleport","gundrop"}) do
            Diag:RegisterModule("features/mm2/"..name..".lua")
        end
        Diag:Module("features/mm2/roletracker.lua",RoleTracker~=nil,"loaded")
        Diag:Module("features/mm2/roundtracker.lua",RoundTracker~=nil,"loaded")
        Diag:Module("features/mm2/esp.lua",ESP~=nil,"loaded")
        Diag:Module("features/mm2/coinfarm.lua",CoinFarm~=nil,"loaded")
        Diag:Module("features/mm2/playerteleport.lua",PlayerTeleport~=nil,"loaded")
        Diag:Module("features/mm2/gundrop.lua",GunDrop~=nil,"loaded")
        -- Structure probes: the named objects the trackers resolve. A rename of
        -- any of these is exactly what silently kills a feature after an update.
        Diag:Probe("Players.LocalPlayer",LocalPlayer~=nil,LocalPlayer and LocalPlayer.Name or "absent")
        Diag:Probe("Workspace.RegularLobby",Workspace:FindFirstChild("RegularLobby")~=nil,
            Workspace:FindFirstChild("RegularLobby") and Workspace.RegularLobby.ClassName or "absent")
        local hasKnife,hasGun,hasDrop,hasCoins=false,false,false,false
        for _,object in ipairs(Workspace:GetDescendants()) do
            if object.Name=="GunDrop" then hasDrop=true end
            if object.Name=="CoinContainer" then hasCoins=true end
        end
        for _,player in ipairs(Players:GetPlayers()) do
            local character=player.Character
            local backpack=player:FindFirstChildOfClass("Backpack")
            if character and character:FindFirstChild("Knife",true) then hasKnife=true end
            if character and character:FindFirstChild("Gun",true) then hasGun=true end
            if backpack and backpack:FindFirstChild("Gun") then hasGun=true end
        end
        Diag:Probe("Tool.Knife",hasKnife,hasKnife and "seen on a player" or "not seen (no murder this round?)")
        Diag:Probe("Tool.Gun",hasGun,hasGun and "seen on a player" or "not seen (no sheriff this round?)")
        Diag:Probe("Workspace.GunDrop",hasDrop,hasDrop and "found" or "no active drop")
        Diag:Probe("Workspace.CoinContainer",hasCoins,hasCoins and "found" or "no container")
        -- Live feature state, read from the tracker debug tables the backend keeps.
        Diag:Feature("MM2.RoleESP",function() return State.Toggles.RoleESP and "ON" or "off" end)
        Diag:Feature("MM2.AutoCoins",function() return State.Toggles.AutoCoins and "ON" or "off" end)
        Diag:Feature("MM2.GunDropESP",function() return State.Toggles.GunDropESP and "ON" or "off" end)
        Diag:Feature("MM2.AutoGetGun",function() return State.Toggles.AutoGetGun and "ON" or "off" end)
        Diag:Feature("MM2.Roles",function()
            local info=RoleTracker:GetDebugInfo()
            return "murder="..tostring(info.Murder).." sheriff="..tostring(info.Sheriff).." scans="..tostring(info.Scans)
        end)
        Diag:Feature("MM2.Round",function()
            local info=RoundTracker:GetDebugInfo()
            return "active="..tostring(info.RoundActive).." alive="..tostring(info.AliveRoundPlayers).." lobby="..tostring(info.PlayersInLobby)
        end)
        Diag:Feature("MM2.CoinFarm",function()
            local info=CoinFarm:GetDebugInfo()
            return "coins="..tostring(info.Coins).." teleports="..tostring(info.Teleports).." paused="..tostring(info.Paused)
        end)
        Diag:Feature("MM2.GunDrop",function()
            local info=GunDrop:GetDebugInfo()
            return "drop="..tostring(info.GunDrop).." dist="..tostring(info.MurderDistance).." safe="..tostring(info.Safe)
        end)
        Diag:Feature("MM2.LastError",function()
            local parts={}
            for _,info in ipairs({RoleTracker:GetDebugInfo(),RoundTracker:GetDebugInfo(),CoinFarm:GetDebugInfo(),PlayerTeleport:GetDebugInfo(),GunDrop:GetDebugInfo()}) do
                if info.LastError and info.LastError~="none" then parts[#parts+1]=tostring(info.LastError) end
            end
            return #parts>0 and table.concat(parts," | ") or "none"
        end)
        if type(Diag.Watch)=="function" then
            Diag:Watch("MM2 murder",function() local info=RoleTracker:GetDebugInfo() return tostring(info.Murder) end)
            Diag:Watch("MM2 round active",function() return tostring(RoundTracker:GetDebugInfo().RoundActive) end)
            Diag:Watch("MM2 coins",function() return tostring(CoinFarm:GetDebugInfo().Coins) end)
            Diag:Watch("MM2 gun drop",function() return tostring(GunDrop:GetDebugInfo().GunDrop) end)
        end
        if type(Diag.Command)=="function" then
            Diag:Command("mm2",function()
                local role=RoleTracker:GetDebugInfo()
                local round=RoundTracker:GetDebugInfo()
                local coin=CoinFarm:GetDebugInfo()
                local gun=GunDrop:GetDebugInfo()
                return "murder="..tostring(role.Murder).." sheriff="..tostring(role.Sheriff)
                    .." roundActive="..tostring(round.RoundActive).." alive="..tostring(round.AliveRoundPlayers)
                    .." coins="..tostring(coin.Coins).." drop="..tostring(gun.GunDrop)
            end)
            Diag:Command("mm2-roleesp",function(argument)
                local on=argument~="off"
                State:SetRoleESP(on)
                return "RoleESP="..tostring(on)
            end)
        end
    end
end

return State


]],
    ["src/games/noobpiece.lua"] = [[
local Workspace=game:GetService("Workspace")
local env=type(getgenv)=="function" and getgenv() or _G
local previous=env.__DEPHUB_NOOBPIECE
if type(previous)=="table" and type(previous.Destroy)=="function" then previous:Destroy() end
local BASE_URL=((type(getgenv)=="function" and getgenv() or _G).__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"

local function loadFeature(path)
    local env=type(getgenv)=="function" and getgenv() or _G
    local cb=tostring((env.__DEPHUB or {}).SourceCacheBust or "")
    local source=__dephubHttpGet(BASE_URL..path..(cb~="" and ("?cb="..cb) or ""))
    local chunk=assert(loadstring(source))
    return chunk()
end

local Movement=loadFeature("src/core/tween-movement.lua")
local MovementProfile=loadFeature("src/games/features/noobpiece/movementprofile.lua")
local IslandData=loadFeature("src/games/features/noobpiece/islanddata.lua")
local ChestESP=loadFeature("src/games/features/noobpiece/chestesp.lua")
local IslandTracker=loadFeature("src/games/features/noobpiece/islandtracker.lua")
local AutoChest=loadFeature("src/games/features/noobpiece/autochest.lua")
local AutoAttack=loadFeature("src/games/features/noobpiece/autoattack.lua")
local AutoFarm=loadFeature("src/games/features/noobpiece/autofarm.lua")
local AutoTeam=loadFeature("src/games/features/noobpiece/autoteam.lua")
local WanderingGacha=loadFeature("src/games/features/noobpiece/wanderinggacha.lua")
local NpcESP=loadFeature("src/games/features/noobpiece/npcesp.lua")
local AutoQuest=loadFeature("src/games/features/noobpiece/autoquest.lua")

local backend={
    Version="0.0.20",
    Destroyed=false,
    TeleportToken=0,
    Toggles={
        ChestESP=false,
        IslandESP=false,
        IslandTeleport=false,
        GachaESP=false,
        AutoQuest=false,
        AutoChest=false,
        AutoAttack=false,
        AutoFarm=false,
        AutoTeam=false,
        AutoFarmMobs=false
    },
    Values={
        AutoChestDelay=0.35,
        WeaponCategory="Fists",
        SelectedTeam="Noob",
        SelectedEnemy="Noob",
        SelectedIsland="HomeIsland"
    }
}

function backend:_RefreshMirageESP()
    if self.Destroyed then return end
    local available=Workspace:FindFirstChild("MysteriousIsland")~=nil

    if not self.Toggles.IslandESP or not available then
        if self.MirageMarker then
            self.MirageMarker:Destroy()
            self.MirageMarker=nil
        end
        return
    end

    local island=IslandData.Get("MysteriousIsland")

    if not island or not island.CFrame or self.MirageMarker then
        return
    end

    local part=Instance.new("Part")
    part.Name="DepHubMysteriousIslandMarker"
    part.Anchored=true
    part.CanCollide=false
    part.CanTouch=false
    part.CanQuery=false
    part.CastShadow=false
    part.Transparency=1
    part.Size=Vector3.new(4,4,4)
    part.CFrame=island.CFrame
    part.Parent=Workspace

    local gui=Instance.new("BillboardGui")
    gui.Name="DepHubMysteriousIslandESP"
    gui.Adornee=part
    gui.AlwaysOnTop=true
    gui.Size=UDim2.fromOffset(190,42)
    gui.StudsOffset=Vector3.new(0,5,0)
    gui.MaxDistance=10000
    gui.LightInfluence=0
    gui.Parent=part

    local label=Instance.new("TextLabel")
    label.BackgroundTransparency=1
    label.Size=UDim2.fromScale(1,1)
    label.Font=Enum.Font.GothamBold
    label.TextColor3=Color3.new(1,1,1)
    label.TextStrokeColor3=Color3.new(0,0,0)
    label.TextStrokeTransparency=0.2
    label.TextSize=13
    label.Text="MYSTERIOUS ISLAND"
    label.Parent=gui

    self.MirageMarker=part
end

function backend:SetChestESP(enabled)
    if self.Destroyed then return false end
    enabled=enabled==true
    self.Toggles.ChestESP=enabled
    self.ChestESP:SetEnabled(enabled)
end

function backend:SetIslandESP(enabled)
    if self.Destroyed then return false end
    enabled=enabled==true
    self.Toggles.IslandESP=enabled
    self.IslandTracker:SetESPEnabled(enabled)
    self:_RefreshMirageESP()
end

function backend:SetSelectedIsland(name)
    if self.Destroyed then return false end
    if type(name)~="string" or name=="" then
        return false
    end

    self.Values.SelectedIsland=name

    if self.Toggles.IslandTeleport then
        self.Movement:CancelOwner("IslandTeleport",true)
        self.TeleportToken+=1
        local token=self.TeleportToken
        task.spawn(function()
            if not self.Destroyed and self.Toggles.IslandTeleport and token==self.TeleportToken then self:TeleportIsland(name) end
        end)
    end

    return true
end

function backend:ConnectIslandAvailabilityChanged(callback)
    return self.IslandAvailability.Event:Connect(callback)
end

function backend:GetIslandNames()
    local names=self.IslandTracker:GetTeleportNames()

    if Workspace:FindFirstChild("MysteriousIsland") and not table.find(names,"MysteriousIsland") then
        names[#names+1]="MysteriousIsland"
    end

    return names
end

function backend:TeleportIsland(name)
    if self.Destroyed then return false end
    name=name or self.Values.SelectedIsland

    if type(name)~="string" or name=="" then
        return false
    end

    if name=="MysteriousIsland" and not Workspace:FindFirstChild("MysteriousIsland") then
        return false
    end

    self.Values.SelectedIsland=name
    return self.IslandTracker:Teleport(name,"IslandTeleport")
end

function backend:SetIslandTeleport(enabled)
    if self.Destroyed then return false end
    enabled=enabled==true
    self.Toggles.IslandTeleport=enabled
    self.TeleportToken+=1

    if not enabled then
        self.Movement:CancelOwner("IslandTeleport",true)
        return true
    end

    local name=self.Values.SelectedIsland

    if name=="MysteriousIsland" and not Workspace:FindFirstChild("MysteriousIsland") then
        self.Toggles.IslandTeleport=false
        return false
    end

    local token=self.TeleportToken
    task.spawn(function()
        if not self.Destroyed and self.Toggles.IslandTeleport and token==self.TeleportToken then self:TeleportIsland(name) end
    end)

    return true
end

function backend:SetAutoChest(enabled)
    if self.Destroyed then return false end
    enabled=enabled==true

    if enabled and self.Toggles.AutoFarm then
        self.Toggles.AutoFarm=false
        self.AutoFarm:SetEnabled(false)
    end

    self.Toggles.AutoChest=enabled
    self.AutoChest:SetEnabled(enabled)
end

function backend:SetAutoFarm(enabled)
    if self.Destroyed then return false end
    enabled=enabled==true

    if enabled and self.Toggles.AutoChest then
        self.Toggles.AutoChest=false
        self.AutoChest:SetEnabled(false)
    end

    self.Toggles.AutoFarm=enabled
    self.AutoFarm:SetEnabled(enabled)
end

function backend:SetSelectedEnemy(name)
    if self.Destroyed then return false end
    if self.AutoFarm:SetSelectedEnemy(name) then
        self.Values.SelectedEnemy=self.AutoFarm:GetSelectedEnemy()
        self.AutoQuest:SetSelectedEnemy(self.Values.SelectedEnemy)
        return true
    end

    return false
end

function backend:GetEnemyTypes()
    return self.AutoFarm:GetEnemyTypes()
end

function backend:GetSelectedEnemyOption()
    return self.AutoFarm:GetSelectedEnemyOption()
end

function backend:TeleportWanderingGacha()
    if self.Destroyed then return false end
    return self.WanderingGacha:Teleport()
end

function backend:SetGachaESP(enabled)
    if self.Destroyed then return false end
    enabled=enabled==true
    self.Toggles.GachaESP=enabled
    self.NpcESP:SetEnabled(enabled)
end

function backend:SetAutoQuest(enabled)
    if self.Destroyed then return false end
    enabled=enabled==true
    self.Toggles.AutoQuest=enabled
    self.AutoQuest:SetEnabled(enabled)
end

function backend:SetWeaponCategory(category)
    if self.Destroyed then return false end
    if self.AutoFarm:SetWeaponCategory(category) then
        self.Values.WeaponCategory=category
        return true
    end

    return false
end

function backend:SetSelectedTeam(name)
    if self.Destroyed then return false end
    if self.AutoTeam:SetSelected(name) then
        self.Values.SelectedTeam=name
        return true
    end

    return false
end

function backend:SetAutoTeam(enabled)
    if self.Destroyed then return false end
    enabled=enabled==true
    self.Toggles.AutoTeam=enabled
    self.AutoTeam:SetEnabled(enabled)
end

function backend:GetTeams()
    return self.AutoTeam:GetTeams()
end

function backend:SetAutoChestDelay(value)
    if self.Destroyed then return false end
    value=math.clamp(tonumber(value) or 0.35,0.1,2)
    self.Values.AutoChestDelay=value
    self.AutoChest:SetDelay(value)
end

function backend:SetAutoAttack(enabled)
    if self.Destroyed then return false end
    enabled=enabled==true
    self.Toggles.AutoAttack=enabled
    self.AutoAttack:SetEnabled(enabled)
end

function backend:GetToggle(name)
    return self.Toggles[name]
end

function backend:GetValue(name)
    return self.Values[name]
end

function backend:GetKnownIslands()
    return self.IslandTracker:GetKnownIslands()
end

function backend:Destroy()
    if self.Destroyed then return end
    self.Destroyed=true
    self.TeleportToken+=1
    for _,name in ipairs({"IslandWorkspaceConnection","IslandWorkspaceRemovingConnection"}) do
        local connection=self[name]
        self[name]=nil
        if connection then connection:Disconnect() end
    end
    for _,name in ipairs({"MirageMarker","IslandAvailability","AutoQuest","NpcESP","WanderingGacha","AutoTeam","AutoFarm","AutoChest","AutoAttack","IslandTracker","ChestESP","Movement"}) do
        local resource=self[name]
        if resource and type(resource.Destroy)=="function" then
            local ok,reason=pcall(resource.Destroy,resource)
            if not ok then warn("[DepHub Noob Piece] cleanup "..name..": "..tostring(reason)) end
        elseif typeof(resource)=="Instance" then
            resource:Destroy()
        end
        self[name]=nil
    end
    if env.__DEPHUB_NOOBPIECE==self then env.__DEPHUB_NOOBPIECE=nil end
    if env.__DEPHUB and env.__DEPHUB.NoobPiece==self then env.__DEPHUB.NoobPiece=nil end
end

local ok,reason=pcall(function()
    backend.Movement=Movement.new(MovementProfile)

    backend.ChestESP=ChestESP.new()
    backend.IslandTracker=IslandTracker.new(IslandData,backend.Movement)
    backend.AutoChest=AutoChest.new(backend.Movement)
    backend.AutoAttack=AutoAttack.new()
    backend.AutoFarm=AutoFarm.new(backend.Movement,backend.AutoAttack,IslandData)
    backend.AutoTeam=AutoTeam.new()
    backend.WanderingGacha=WanderingGacha.new(backend.Movement)
    backend.NpcESP=NpcESP.new()
    backend.AutoQuest=AutoQuest.new(backend.Movement,IslandData,backend.AutoFarm)

    backend.AutoChest:SetDelay(backend.Values.AutoChestDelay)
    backend.AutoFarm:SetWeaponCategory(backend.Values.WeaponCategory)
    backend.AutoTeam:SetSelected(backend.Values.SelectedTeam)
    backend.AutoFarm:SetSelectedEnemy(backend.Values.SelectedEnemy)
    backend.AutoQuest:SetSelectedEnemy(backend.Values.SelectedEnemy)
    backend.IslandTracker:Start()
    backend.IslandAvailability=Instance.new("BindableEvent")
    backend.MirageMarker=nil

    backend.IslandWorkspaceConnection=Workspace.ChildAdded:Connect(function(child)
        if child.Name=="MysteriousIsland" then
            backend:_RefreshMirageESP()
            backend.IslandAvailability:Fire(backend:GetIslandNames())
        end
    end)

    backend.IslandWorkspaceRemovingConnection=Workspace.ChildRemoved:Connect(function(child)
        if child.Name=="MysteriousIsland" then
            backend:_RefreshMirageESP()

            if backend.Toggles.IslandTeleport and backend.Values.SelectedIsland=="MysteriousIsland" then
                backend:SetIslandTeleport(false)
            end

            backend.IslandAvailability:Fire(backend:GetIslandNames())
        end
    end)

end)
if not ok then
    backend:Destroy()
    error("Noob Piece initialization failed: "..tostring(reason))
end

local UI=(env.__DEPHUB or {}).UI
-- ---------------------------------------------------------------------------
-- Presentation: grouped by CATEGORY (finalidade), never by game name. This game
-- uses only the categories it actually has:
--   Farm     - the farm/premium loop (attack, quest, chest, weapon)
--   Visual   - what to see (chest / island / NPC ESP)
--   Movement - island travel and teleports
--   Player   - team selection and auto-team
-- The category -> tab -> section creation goes through the shared UI kit.
-- ---------------------------------------------------------------------------
do
    local Kit=env.__DEPHUB and env.__DEPHUB.UIKit
    if Kit then
        local farming=Kit.Section(Kit.Tab("Farm","Farm"),"Automation","Left")
        if farming then
            -- The four automation switches share lines; chest interval drives Auto
            -- chest so it keeps its row, and the two dropdowns keep theirs.
            local farmRow1=Kit.Row(farming)
            if farmRow1 then
                farmRow1:CreateToggle("Auto farm",backend.Toggles.AutoFarm,function(v) backend:SetAutoFarm(v) end)
                farmRow1:CreateToggle("Auto attack",backend.Toggles.AutoAttack,function(v) backend:SetAutoAttack(v) end)
            else
                farming:CreateToggle("Auto farm",backend.Toggles.AutoFarm,function(v) backend:SetAutoFarm(v) end)
                farming:CreateToggle("Auto attack",backend.Toggles.AutoAttack,function(v) backend:SetAutoAttack(v) end)
            end
            local farmRow2=Kit.Row(farming)
            if farmRow2 then
                farmRow2:CreateToggle("Auto quest",backend.Toggles.AutoQuest,function(v) backend:SetAutoQuest(v) end)
                farmRow2:CreateToggle("Auto chest",backend.Toggles.AutoChest,function(v) backend:SetAutoChest(v) end)
            else
                farming:CreateToggle("Auto quest",backend.Toggles.AutoQuest,function(v) backend:SetAutoQuest(v) end)
                farming:CreateToggle("Auto chest",backend.Toggles.AutoChest,function(v) backend:SetAutoChest(v) end)
            end
            farming:CreateSlider("Chest interval",0.1,2,backend.Values.AutoChestDelay,function(v) backend:SetAutoChestDelay(v) end)
            farming:CreateDropdown("Weapon type",{"Fists","Sword"},backend.Values.WeaponCategory,function(v) backend:SetWeaponCategory(v) end)
            local enemies=backend:GetEnemyTypes()
            if type(enemies)=="table" and #enemies>0 then
                farming:CreateDropdown("Enemy",enemies,backend.Values.SelectedEnemy,function(v) backend:SetSelectedEnemy(v) end)
            end
        end

        local visuals=Kit.Section(Kit.Tab("ESP","Visual"),"Exploration","Left")
        if visuals then
            -- The three ESP switches are the same decision; pair two, then one.
            local espRow=Kit.Row(visuals)
            if espRow then
                espRow:CreateToggle("Chest ESP",backend.Toggles.ChestESP,function(v) backend:SetChestESP(v) end)
                espRow:CreateToggle("Island ESP",backend.Toggles.IslandESP,function(v) backend:SetIslandESP(v) end)
            else
                visuals:CreateToggle("Chest ESP",backend.Toggles.ChestESP,function(v) backend:SetChestESP(v) end)
                visuals:CreateToggle("Island ESP",backend.Toggles.IslandESP,function(v) backend:SetIslandESP(v) end)
            end
            visuals:CreateToggle("NPC ESP",backend.Toggles.GachaESP,function(v) backend:SetGachaESP(v) end)
        end

        local travel=Kit.Section(Kit.Tab("Travel","Movement"),"Teleport","Left")
        if travel then
            local islands=backend:GetIslandNames()
            if type(islands)=="table" and #islands>0 then
                travel:CreateDropdown("Island",islands,backend.Values.SelectedIsland,function(v) backend:SetSelectedIsland(v) end)
            end
            -- Auto teleport + the two go-buttons share the action row.
            local travelRow=Kit.Row(travel)
            if travelRow then
                travelRow:CreateToggle("Auto teleport to island",backend.Toggles.IslandTeleport,function(v) backend:SetIslandTeleport(v) end)
                travelRow:CreateButton("Go to selected island",function()
                    local ok=backend:TeleportIsland(backend.Values.SelectedIsland)
                    if UI and type(UI.Notify)=="function" then UI:Notify("Noob Piece",ok and "Teleport started." or "Could not teleport.") end
                end)
            else
                travel:CreateToggle("Auto teleport to island",backend.Toggles.IslandTeleport,function(v) backend:SetIslandTeleport(v) end)
                travel:CreateButton("Go to selected island",function()
                    local ok=backend:TeleportIsland(backend.Values.SelectedIsland)
                    if UI and type(UI.Notify)=="function" then UI:Notify("Noob Piece",ok and "Teleport started." or "Could not teleport.") end
                end)
            end
            travel:CreateButton("Go to Wandering Gacha",function()
                local ok=backend:TeleportWanderingGacha()
                if UI and type(UI.Notify)=="function" then UI:Notify("Noob Piece",ok and "Teleport started." or "Gacha not found.") end
            end)
        end

        local team=Kit.Section(Kit.Tab("Team","Player"),"Team","Left")
        if team then
            local teams=backend:GetTeams()
            if type(teams)=="table" and #teams>0 then
                team:CreateDropdown("Team",teams,backend.Values.SelectedTeam,function(v) backend:SetSelectedTeam(v) end)
            end
            team:CreateToggle("Auto team",backend.Toggles.AutoTeam,function(v) backend:SetAutoTeam(v) end)
        end
    end
end

-- Report this backend's own structure and live state into the shared Debug tab.
-- The island systems key off a single Workspace folder, "MysteriousIsland"; a
-- rename there disables its ESP/teleport, so it is probed explicitly.
do
    local Diag=env.__DEPHUB and env.__DEPHUB.Diagnostics
    if Diag and type(Diag.Probe)=="function" then
        Diag:SetEnvironment({["NoobPiece version"]=backend.Version})
        for _,name in ipairs({"movementprofile","islanddata","chestesp","islandtracker","autochest","autoattack","autofarm","autoteam","wanderinggacha","npcesp","autoquest"}) do
            Diag:RegisterModule("features/noobpiece/"..name..".lua")
        end
        Diag:Module("features/noobpiece/islanddata.lua",backend.IslandTracker~=nil,"loaded")
        Diag:Module("features/noobpiece/chestesp.lua",backend.ChestESP~=nil,"loaded")
        Diag:Module("features/noobpiece/islandtracker.lua",backend.IslandTracker~=nil,"loaded")
        Diag:Module("features/noobpiece/autochest.lua",backend.AutoChest~=nil,"loaded")
        Diag:Module("features/noobpiece/autoattack.lua",backend.AutoAttack~=nil,"loaded")
        Diag:Module("features/noobpiece/autofarm.lua",backend.AutoFarm~=nil,"loaded")
        Diag:Module("features/noobpiece/autoteam.lua",backend.AutoTeam~=nil,"loaded")
        Diag:Module("features/noobpiece/wanderinggacha.lua",backend.WanderingGacha~=nil,"loaded")
        Diag:Module("features/noobpiece/npcesp.lua",backend.NpcESP~=nil,"loaded")
        Diag:Module("features/noobpiece/autoquest.lua",backend.AutoQuest~=nil,"loaded")
        Diag:Probe("Workspace.MysteriousIsland",Workspace:FindFirstChild("MysteriousIsland")~=nil,
            Workspace:FindFirstChild("MysteriousIsland") and Workspace.MysteriousIsland.ClassName or "absent (island ESP/teleport turn off)")
        Diag:Probe("Workspace.ChildAdded",backend.IslandWorkspaceConnection~=nil,backend.IslandWorkspaceConnection and "on" or "off")
        Diag:Probe("Workspace.ChildRemoved",backend.IslandWorkspaceRemovingConnection~=nil,backend.IslandWorkspaceRemovingConnection and "on" or "off")
        Diag:Probe("IslandAvailability",backend.IslandAvailability~=nil,backend.IslandAvailability and "BindableEvent" or "absent")
        Diag:Feature("NoobPiece.ChestESP",function() return backend.Toggles.ChestESP and "ON" or "off" end)
        Diag:Feature("NoobPiece.IslandESP",function() return backend.Toggles.IslandESP and "ON" or "off" end)
        Diag:Feature("NoobPiece.IslandTeleport",function() return backend.Toggles.IslandTeleport and "ON" or "off" end)
        Diag:Feature("NoobPiece.GachaESP",function() return backend.Toggles.GachaESP and "ON" or "off" end)
        Diag:Feature("NoobPiece.AutoQuest",function() return backend.Toggles.AutoQuest and "ON" or "off" end)
        Diag:Feature("NoobPiece.AutoChest",function() return backend.Toggles.AutoChest and "ON" or "off" end)
        Diag:Feature("NoobPiece.AutoAttack",function() return backend.Toggles.AutoAttack and "ON" or "off" end)
        Diag:Feature("NoobPiece.AutoFarm",function() return backend.Toggles.AutoFarm and "ON" or "off" end)
        Diag:Feature("NoobPiece.AutoTeam",function() return backend.Toggles.AutoTeam and "ON" or "off" end)
        Diag:Feature("NoobPiece.SelectedIsland",function() return tostring(backend.Values.SelectedIsland) end)
        if type(Diag.Watch)=="function" then
            Diag:Watch("NoobPiece MysteriousIsland",function() return tostring(Workspace:FindFirstChild("MysteriousIsland")~=nil) end)
            Diag:Watch("NoobPiece ilha selecionada",function() return tostring(backend.Values.SelectedIsland) end)
            Diag:Watch("NoobPiece toggles",function()
                local on={}
                for _,name in ipairs({"ChestESP","IslandESP","IslandTeleport","GachaESP","AutoQuest","AutoChest","AutoAttack","AutoFarm","AutoTeam"}) do
                    if backend.Toggles[name] then on[#on+1]=name end
                end
                return #on>0 and table.concat(on,",") or "none"
            end)
        end
        if type(Diag.Command)=="function" then
            Diag:Command("np",function()
                local on={}
                for _,name in ipairs({"ChestESP","IslandESP","IslandTeleport","GachaESP","AutoQuest","AutoChest","AutoAttack","AutoFarm","AutoTeam"}) do
                    if backend.Toggles[name] then on[#on+1]=name end
                end
                return "island="..tostring(backend.Values.SelectedIsland)
                    .." mystic="..tostring(Workspace:FindFirstChild("MysteriousIsland")~=nil)
                    .." on="..(#on>0 and table.concat(on,",") or "none")
            end)
            Diag:Command("np-autofarm",function(argument)
                local on=argument~="off"
                backend:SetAutoFarm(on)
                return "AutoFarm="..tostring(on)
            end)
        end
    end
end
env.__DEPHUB_NOOBPIECE=backend
return backend

]],
    ["src/games/rt3.lua"] = [[
local game = game
local task = task
local pcall = pcall
local tostring = tostring
local type = type
local print = print
local warn = warn

local function log(message)
    pcall(print, "[DEPHUB RT3] " .. tostring(message))
end

local function logWarn(message)
    pcall(warn, "[DEPHUB RT3] " .. tostring(message))
end

local compiler = loadstring
if type(compiler) ~= "function" then
    logWarn("loadstring indisponivel.")
    return false
end

local BASE_URL = ((type(getgenv)=="function" and getgenv() or _G).__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"

local function fetch(path)
    local cb = tostring((type(getgenv)=="function" and getgenv() or _G).__DEPHUB and ((type(getgenv)=="function" and getgenv() or _G).__DEPHUB or {}).SourceCacheBust or "")
    local url = BASE_URL .. path .. (cb ~= "" and ("?cb=" .. cb) or "")
    local ok, result = pcall(function()
        return __dephubHttpGet(url)
    end)

    if ok and type(result) == "string" and #result > 0 then
        return true, result, url
    end

    if not ok then
        return false, tostring(result), url
    end

    return false, "Resposta vazia", url
end

local function loadModule(path)
    log("Carregando modulo: " .. path)
    local okFetch, raw, url = fetch(path)
    if not okFetch then
        logWarn("Falha no modulo " .. path .. ": " .. tostring(raw))
        return nil
    end

    local okCompile, chunk, compileError = pcall(compiler, raw)
    if not okCompile then
        logWarn("Erro compilando " .. path .. ": " .. tostring(chunk))
        return nil
    end

    if type(chunk) ~= "function" then
        logWarn("Codigo invalido em " .. path .. ": " .. tostring(compileError))
        return nil
    end

    local okRun, result = pcall(chunk)
    if not okRun then
        logWarn("Error running " .. path .. ": " .. tostring(result))
        return nil
    end

    log("Module loaded: " .. path)
    return result
end

log("Inicializando Restaurant Tycoon 3")

local corePaths = {
    "src/core/scheduler.lua",
    "src/core/health-monitor.lua",
    "src/core/dashboard.lua",
    "src/core/runtime.lua",
    "src/core/anti-afk.lua"
}
local core = {}
for _, path in ipairs(corePaths) do
    core[path] = loadModule(path)
end

local Scheduler = core["src/core/scheduler.lua"]
local HealthMonitor = core["src/core/health-monitor.lua"]
local Dashboard = core["src/core/dashboard.lua"]
local Runtime = core["src/core/runtime.lua"]
local AntiAFK = core["src/core/anti-afk.lua"]

if not Scheduler or type(Scheduler.new) ~= "function" then
    logWarn("Scheduler indisponivel. Abortando inicializacao.")
    return false
end

if not HealthMonitor or type(HealthMonitor.new) ~= "function" then
    logWarn("Health Monitor indisponivel. Abortando inicializacao.")
    return false
end

if not Dashboard or type(Dashboard.new) ~= "function" then
    logWarn("Dashboard provider indisponivel. Abortando inicializacao.")
    return false
end

if not Runtime or type(Runtime.new) ~= "function" then
    logWarn("Runtime indisponivel. Abortando inicializacao.")
    return false
end

if not AntiAFK or type(AntiAFK.Start) ~= "function" then
    logWarn("Anti-AFK indisponivel. Abortando inicializacao.")
    return false
end

local env = type(getgenv) == "function" and getgenv() or _G
local previousRuntime = env.__DEPHUB and env.__DEPHUB.Runtime
if type(previousRuntime) == "table" and type(previousRuntime.Destroy) == "function" then
    pcall(previousRuntime.Destroy, previousRuntime)
end

local okRuntime, runtime = pcall(function()
    return Runtime.new({
        Scheduler = Scheduler,
        HealthMonitor = HealthMonitor,
        Dashboard = Dashboard,
        SchedulerOptions = {
            DefaultInterval = 0.1,
            MaxErrors = 5
        },
        HealthOptions = {
            Interval = 2,
            MaxErrors = 5
        },
        DashboardOptions = {
            Interval = 1,
            ManifestInterval = 30
        }
    })
end)

if not okRuntime or type(runtime) ~= "table" then
    logWarn("Falha criando Runtime: " .. tostring(runtime))
    return false
end

env.__DEPHUB = env.__DEPHUB or {}
env.__DEPHUB.Runtime = runtime
runtime.Features = {}
local destroyRuntime = runtime.Destroy
function runtime:Destroy()
    if self.Destroyed then return end
    for _, feature in pairs(self.Features) do
        local handler = feature.Toggle or feature.Set
        if type(handler) == "function" then pcall(handler, false) end
    end
    self.Features = {}
    pcall(AntiAFK.Stop)
    local handles={Scheduler=self.Scheduler,HealthMonitor=self.HealthMonitor,Dashboard=self.Dashboard,AntiAFK=AntiAFK}
    destroyRuntime(self)
    if env.__DEPHUB then
        if env.__DEPHUB.Runtime==self then env.__DEPHUB.Runtime=nil end
        for name,handle in pairs(handles) do if env.__DEPHUB[name]==handle then env.__DEPHUB[name]=nil end end
    end
    if env.__DEPHUB_DASHBOARD==handles.Dashboard then env.__DEPHUB_DASHBOARD=nil end
end
env.__DEPHUB.Scheduler = runtime.Scheduler
env.__DEPHUB.HealthMonitor = runtime.HealthMonitor
env.__DEPHUB.Dashboard = runtime.Dashboard
env.__DEPHUB.AntiAFK = AntiAFK
env.__DEPHUB_DASHBOARD = runtime.Dashboard

runtime.HealthMonitor:Register("Dashboard", function()
    local data = runtime.Dashboard and runtime.Dashboard:Get()
    return type(data) == "table" and data.GameId ~= nil
end)

runtime.HealthMonitor:Register("Runtime", function()
    return not runtime.Destroyed
end)

local okStart, startError = pcall(runtime.Start, runtime)
if not okStart then
    logWarn("Falha iniciando Runtime: " .. tostring(startError))
    AntiAFK.Stop()
    runtime:Destroy()
    return false
end

local okAntiAFK, antiAFKError = pcall(AntiAFK.Start)
if not okAntiAFK then
    logWarn("Falha iniciando Anti-AFK: " .. tostring(antiAFKError))
end

local featurePaths = {
    "src/games/features/restauranttycoon3/autofarm.lua",
    "src/games/features/restauranttycoon3/instant-cook.lua",
    "src/games/features/restauranttycoon3/drops.lua",
    "src/games/features/restauranttycoon3/autofarm-friends.lua"
}
local modules = {}
for _, path in ipairs(featurePaths) do
