                end)
                farm:CreateToggle("Friends farm",runtime.Features.AutoFarmFriends and runtime.Features.AutoFarmFriends.Enabled==true,function(v)
                    if runtime.Features.AutoFarmFriends then runtime.Features.AutoFarmFriends.Toggle(v) end
                end)
            end
        end

        local kitchen=Kit.Section(Kit.Tab("Kitchen","Farm"),"Kitchen","Left")
        if kitchen then
            -- Both kitchen switches are the same station automation; one line.
            local kitchenRow=Kit.Row(kitchen)
            if kitchenRow then
                kitchenRow:CreateToggle("Instant cook",runtime.Features.InstantCook and runtime.Features.InstantCook.Enabled==true,function(v)
                    if runtime.Features.InstantCook then runtime.Features.InstantCook.Toggle(v) end
                end)
                kitchenRow:CreateToggle("Collect drops",runtime.Features.AutoDrop and runtime.Features.AutoDrop.Enabled==true,function(v)
                    if runtime.Features.AutoDrop then runtime.Features.AutoDrop.Toggle(v) end
                end)
            else
                kitchen:CreateToggle("Instant cook",runtime.Features.InstantCook and runtime.Features.InstantCook.Enabled==true,function(v)
                    if runtime.Features.InstantCook then runtime.Features.InstantCook.Toggle(v) end
                end)
                kitchen:CreateToggle("Collect drops",runtime.Features.AutoDrop and runtime.Features.AutoDrop.Enabled==true,function(v)
                    if runtime.Features.AutoDrop then runtime.Features.AutoDrop.Toggle(v) end
                end)
            end
        end

        local status=Kit.Section(Kit.Tab("Status","Misc"),"Runtime","Left")
        if status then status:CreateParagraph("DepHub","Restaurant Tycoon 3 loaded. The controls drive the functions registered in the runtime.") end
    end
end
return true
end

registerFeature("AutoFarm", AutoFarm)
registerFeature("InstantCook", InstantCook)
registerFeature("AutoDrop", AutoDrop)
registerFeature("AutoFarmFriends", AutoFarmFriends)

if RegisteredFeatures == 0 then
    logWarn("No feature was registered.")
    AntiAFK.Stop()
    runtime:Destroy()
    return false
end

local snapshot = runtime:GetSnapshot()
local dashboardData = snapshot.Dashboard or {}

log("Dashboard: " .. tostring(dashboardData.GameName or "Unknown") .. " | Ping: " .. tostring(dashboardData.Ping or "Unknown") .. " ms | FPS: " .. tostring(dashboardData.FPS or "Unknown") .. " | Script: " .. tostring(dashboardData.ScriptVersion or "Unknown") .. " | Executor: " .. tostring(dashboardData.Executor or "Unknown"))
log("Runtime health: " .. tostring(snapshot.Health))
log("Restaurant Tycoon 3 inicializado com sucesso")

-- Report the RT3 runtime into the shared Debug tab. This backend has no direct
-- game-structure dependency (every module is fetched over HTTP), so its real
-- failure surface is the loader and runtime: a module that failed to fetch, a
-- feature missing its Toggle/Set contract, or a health check that went stale.
do
    local Diag=env.__DEPHUB and env.__DEPHUB.Diagnostics
    if Diag and type(Diag.Probe)=="function" then
        Diag:SetEnvironment({["RT3 features"]=tostring(RegisteredFeatures)})
        for _,path in ipairs(featurePaths) do
            Diag:RegisterModule(path)
            local loaded=modules[path]
            local hasHandler=type(loaded)=="table" and type(loaded.Toggle or loaded.Set)=="function"
            Diag:Module(path,loaded~=nil,loaded and (hasHandler and "loaded" or "no Toggle/Set") or "absent")
        end
        Diag:Probe("runtime.Start",runtime~=nil,runtime and "ok" or "absent")
        Diag:Probe("Runtime.Dashboard",runtime.Dashboard~=nil,runtime.Dashboard and "on" or "absent")
        Diag:Probe("Runtime.HealthMonitor",runtime.HealthMonitor~=nil,runtime.HealthMonitor and "on" or "absent")
        Diag:Probe("Runtime.Scheduler",runtime.Scheduler~=nil,runtime.Scheduler and "on" or "absent")
        Diag:Probe("AntiAFK",env.__DEPHUB and env.__DEPHUB.AntiAFK~=nil,env.__DEPHUB and env.__DEPHUB.AntiAFK and "on" or "absent")
        Diag:Probe("Registered features",RegisteredFeatures>0,RegisteredFeatures.." of "..#featurePaths)
        Diag:Feature("RT3.AutoFarm",function() return runtime.Features.AutoFarm and tostring(runtime.Features.AutoFarm.Enabled) or "absent" end)
        Diag:Feature("RT3.AutoFarmFriends",function() return runtime.Features.AutoFarmFriends and tostring(runtime.Features.AutoFarmFriends.Enabled) or "absent" end)
        Diag:Feature("RT3.InstantCook",function() return runtime.Features.InstantCook and tostring(runtime.Features.InstantCook.Enabled) or "absent" end)
        Diag:Feature("RT3.AutoDrop",function() return runtime.Features.AutoDrop and tostring(runtime.Features.AutoDrop.Enabled) or "absent" end)
        Diag:Feature("RT3.Health",function()
            local snap=runtime:GetSnapshot()
            return snap and tostring(snap.Health) or "no snapshot"
        end)
        if type(Diag.Watch)=="function" then
            Diag:Watch("RT3 health",function() local snap=runtime:GetSnapshot() return snap and tostring(snap.Health) or "?" end)
            Diag:Watch("RT3 features",function()
                local n=0
                for _ in pairs(runtime.Features) do n=n+1 end
                return n
            end)
            Diag:Watch("RT3 destroyed",function() return tostring(runtime.Destroyed) end)
        end
        if type(Diag.Command)=="function" then
            Diag:Command("rt3",function()
                local snap=runtime:GetSnapshot() or {}
                local data=snap.Dashboard or {}
                local names={}
                for name in pairs(runtime.Features) do names[#names+1]=name end
                table.sort(names)
                return "features="..table.concat(names,",")
                    .." health="..tostring(snap.Health)
                    .." executor="..tostring(data.Executor)
                    .." destroyed="..tostring(runtime.Destroyed)
            end)
        end
    end
end

return true


]],
    ["src/games/steal-a-egg.lua"] = [[
local game, task, type, tostring, tonumber, pairs, ipairs, pcall, math, table = game, task, type, tostring, tonumber, pairs, ipairs, pcall, math, table
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")

local LocalPlayer = Players.LocalPlayer
local env = type(getgenv) == "function" and getgenv() or _G
local STATE_KEY = "__DEPHUB_STEALANEGG"

local previous = env[STATE_KEY]
if type(previous) == "table" and type(previous.Destroy) == "function" then
    pcall(previous.Destroy, previous)
end

if not LocalPlayer then
    return false
end

-- Steal An Egg backend.
--
-- Two features, both ported from the Blox Fruits modules and only those:
--
--   * Walk speed -- a toggle + slider driven by a RenderStepped loop that
--     re-applies Humanoid.WalkSpeed every frame, so the game's controller cannot
--     overwrite it (RenderStepped runs after it and wins the frame).
--   * Teleport -- a CFrame tween fly, ported from the BF teleport module: it
--     tweens the HumanoidRootPart to the target at a constant speed, zeroes the
--     linear velocity during the tween and turns collision off so the character
--     glides instead of snagging, but it never Anchors the character (anchoring
--     makes both games reject every hit). Waypoints let the player save spots in
--     game, because the coordinates are not known ahead of time.
--
-- The teleport is a client-side CFrame move. It works in games that trust the
-- client for position, which Blox Fruits does. Whether Steal An Egg does as well
-- is a property of that game, not of this code: a server-side position check
-- would flag it no matter how the tween is shaped.

local State = {
    Version = "0.2.0",
    Destroyed = false,
    Started = false,
    Connections = {},
    Toggles = {
        Speed = false,
    },
    ToggleLabels = {
        Speed = "Speed boost",
    },
    Values = {
        WalkSpeed = 50,
        FlySpeed = 200,
    },
    Tween = nil,
    Waypoints = {},
}

env[STATE_KEY] = State
env.__DEPHUB = env.__DEPHUB or {}
env.__DEPHUB.StealAnEgg = State

local function myCharacter()
    return LocalPlayer.Character
end

local function myHumanoid()
    local character = myCharacter()
    if not character then return nil end
    return character:FindFirstChildOfClass("Humanoid")
end

local function myRoot()
    local character = myCharacter()
    if not character then return nil end
    return character:FindFirstChild("HumanoidRootPart")
end

-- ---------------------------------------------------------------------------
-- Walk speed (unchanged from v0.0.78)
-- ---------------------------------------------------------------------------
function State:SetSpeed(value)
    value = tonumber(value)
    if not value or value ~= value then return false end
    self.Values.WalkSpeed = math.clamp(math.floor(value), 16, 300)
    return true
end

-- ---------------------------------------------------------------------------
-- Teleport: CFrame tween fly ported from the Blox Fruits teleport module.
-- ---------------------------------------------------------------------------
function State:CancelFly()
    if self.Tween then pcall(function() self.Tween:Cancel() end); self.Tween = nil end
end

function State:Go(pos)
    if self.Destroyed or typeof(pos) ~= "Vector3" then return false end
    local root = myRoot()
    if not root then return false end
    local distance = (root.Position - pos).Magnitude
    local duration = math.clamp(distance / math.max(self.Values.FlySpeed, 1), 0.05, 90)
    self:CancelFly()
    local tween = TweenService:Create(root, TweenInfo.new(duration, Enum.EasingStyle.Linear), {CFrame = CFrame.new(pos)})
    self.Tween = tween
    tween.Completed:Connect(function() if self.Tween == tween then self.Tween = nil end end)
    tween:Play()
    return true
end

function State:FlyToPosition()
    local root = myRoot()
    if not root then return nil end
    local p = root.Position
    return p
end

function State:SetFlySpeed(value)
    value = tonumber(value)
    if not value or value ~= value or value < 1 then return false end
    self.Values.FlySpeed = math.clamp(math.floor(value), 1, 100000)
    return true
end

-- ---------------------------------------------------------------------------
-- Waypoints: the map layout is not known ahead of time, so the player saves the
-- spots in game. Persisted through the executor file API when available; a
-- missing writefile/readfile degrades to in-memory only instead of erroring.
-- ---------------------------------------------------------------------------
local WAYPOINT_FILE = "DepHub_SAE_waypoints.json"

local function canPersist()
    return type(writefile) == "function" and type(readfile) == "function"
end

local function encodeWaypoints(list)
    local lines = {}
    for _, w in ipairs(list) do
        lines[#lines + 1] = string.format("%s\t%.3f\t%.3f\t%.3f", w.name, w.pos.X, w.pos.Y, w.pos.Z)
    end
    return table.concat(lines, "\n")
end

local function decodeWaypoints(text)
    local list = {}
    for line in tostring(text):gmatch("[^\n]+") do
        local name, x, y, z = line:match("^(.-)\t([%-%d%.]+)\t([%-%d%.]+)\t([%-%d%.]+)$")
        if name and x and y and z then
            list[#list + 1] = {name = name, pos = Vector3.new(tonumber(x), tonumber(y), tonumber(z))}
        end
    end
    return list
end

function State:SaveWaypoints()
    if not canPersist() then return false end
    local ok = pcall(writefile, WAYPOINT_FILE, encodeWaypoints(self.Waypoints))
    return ok
end

function State:LoadWaypoints()
    if not canPersist() then return false end
    local has = pcall(isfile, WAYPOINT_FILE)
    if not (has and isfile(WAYPOINT_FILE)) then return false end
    local ok, text = pcall(readfile, WAYPOINT_FILE)
    if not ok or type(text) ~= "string" then return false end
    self.Waypoints = decodeWaypoints(text)
    return true
end

function State:AddWaypoint(name, pos)
    if self.Destroyed then return false end
    local root = myRoot()
    pos = pos or (root and root.Position)
    if not pos then return false end
    name = tostring(name or "")
    if name == "" then name = "WP " .. (#self.Waypoints + 1) end
    self.Waypoints[#self.Waypoints + 1] = {name = name, pos = pos}
    self:SaveWaypoints()
    return true
end

function State:RemoveWaypoint(name)
    if self.Destroyed then return false end
    for index, w in ipairs(self.Waypoints) do
        if w.name == name then
            table.remove(self.Waypoints, index)
            self:SaveWaypoints()
            return true
        end
    end
    return false
end

-- ---------------------------------------------------------------------------
-- Toggles + lifecycle
-- ---------------------------------------------------------------------------
function State:SetToggle(name, enabled)
    if self.Destroyed or type(name) ~= "string" then return false end
    if self.Toggles[name] == nil then return false end
    self.Toggles[name] = enabled == true
    -- Turning the boost off hands the value back to the game immediately, so the
    -- player is not stuck at the boosted speed until the next respawn.
    if name == "Speed" and not self.Toggles.Speed then
        local humanoid = myHumanoid()
        if humanoid then pcall(function() humanoid.WalkSpeed = 16 end) end
    end
    return true
end

function State:GetToggle(name)
    if self.Destroyed or type(name) ~= "string" then return false end
    return self.Toggles[name] == true
end

function State:Start()
    if self.Started or self.Destroyed then return false end
    self.Started = true

    -- Walk speed: re-apply every frame while the boost is on.
    self.Connections[#self.Connections + 1] = RunService.RenderStepped:Connect(function()
        if self.Destroyed or not self.Toggles.Speed then return end
        local humanoid = myHumanoid()
        if humanoid then humanoid.WalkSpeed = self.Values.WalkSpeed end
    end)

    -- During a fly: zero velocity + collision off, exactly like BF. Never Anchor
    -- the character -- anchoring makes both games reject every hit.
    self.Connections[#self.Connections + 1] = RunService.Heartbeat:Connect(function()
        if self.Destroyed or not self.Tween then return end
        local character = myCharacter()
        if not character then return end
        local root = character:FindFirstChild("HumanoidRootPart")
        if root then root.AssemblyLinearVelocity = Vector3.zero end
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") and part.CanCollide then part.CanCollide = false end
        end
    end)

    return true
end

function State:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    self:CancelFly()
    local humanoid = myHumanoid()
    if humanoid then pcall(function() humanoid.WalkSpeed = 16 end) end
    for _, connection in ipairs(self.Connections) do
        pcall(function() connection:Disconnect() end)
    end
    self.Connections = {}
    if env[STATE_KEY] == self then env[STATE_KEY] = nil end
    if env.__DEPHUB and env.__DEPHUB.StealAnEgg == self then env.__DEPHUB.StealAnEgg = nil end
end

-- ---------------------------------------------------------------------------
-- Presentation: grouped by CATEGORY (finalidade), never a per-game tab. Speed
-- and teleport are both movement, so they live in the Movement category.
-- ---------------------------------------------------------------------------
do
    local UI = env.__DEPHUB and env.__DEPHUB.UI
    local Kit = env.__DEPHUB and env.__DEPHUB.UIKit
    if Kit then
        local speed = Kit.Section(Kit.Tab("Speed", "Movement"), "Movement", "Left")
        if speed then
            -- The switch and the speed it sets share a line.
            local speedRow = Kit.Row(speed)
            if speedRow then
                speedRow:CreateToggle("Speed boost", State.Toggles.Speed, function(v) State:SetToggle("Speed", v) end)
                speedRow:CreateSlider("Walk speed", 16, 300, State.Values.WalkSpeed, function(v) State:SetSpeed(v) end)
            else
                speed:CreateToggle("Speed boost", State.Toggles.Speed, function(v) State:SetToggle("Speed", v) end)
                speed:CreateSlider("Walk speed", 16, 300, State.Values.WalkSpeed, function(v) State:SetSpeed(v) end)
            end
        end

        local tpTab = Kit.Tab("Teleport", "Movement")
        local fly = Kit.Section(tpTab, "Flight", "Left")
        if fly then
            fly:CreateSlider("Flight speed", 50, 1000, State.Values.FlySpeed, function(v) State:SetFlySpeed(v) end)
            -- The two position actions are the same shape; one line.
            local flyRow = Kit.Row(fly)
            if flyRow then
                flyRow:CreateButton("Report current position", function()
                    local p = State:FlyToPosition()
                    if not p then UI:Notify("Teleport", "No character") return end
                    UI:Notify("Position", string.format("X %.1f  Y %.1f  Z %.1f", p.X, p.Y, p.Z))
                end)
                flyRow:CreateButton("Save waypoint here", function()
                    local p = State:FlyToPosition()
                    if not p then UI:Notify("Teleport", "No character") return end
                    State:AddWaypoint(nil, p)
                    UI:Notify("Waypoint", "Saved (total " .. tostring(#State.Waypoints) .. ")")
                end)
            else
                fly:CreateButton("Report current position", function()
                    local p = State:FlyToPosition()
                    if not p then UI:Notify("Teleport", "No character") return end
                    UI:Notify("Position", string.format("X %.1f  Y %.1f  Z %.1f", p.X, p.Y, p.Z))
                end)
                fly:CreateButton("Save waypoint here", function()
                    local p = State:FlyToPosition()
                    if not p then UI:Notify("Teleport", "No character") return end
                    State:AddWaypoint(nil, p)
                    UI:Notify("Waypoint", "Saved (total " .. tostring(#State.Waypoints) .. ")")
                end)
            end
        end

        local wp = Kit.Section(tpTab, "Waypoints", "Right")
        if wp then
            for _, waypoint in ipairs(State.Waypoints) do
                wp:CreateButton("Go: " .. waypoint.name, function() State:Go(waypoint.pos) end)
            end
            wp:CreateParagraph("Waypoints", "None saved yet. Use 'Save waypoint here' in the left column while standing where you want it.")
        end
    end
end

State:LoadWaypoints()
State:Start()

do
    local Diag = env.__DEPHUB and env.__DEPHUB.Diagnostics
    if Diag and type(Diag.RegisterModule) == "function" then
        Diag:RegisterModule("src/games/steal-a-egg.lua")
        Diag:Feature("StealAnEgg.Speed", function() return State.Toggles.Speed and ("ON " .. tostring(State.Values.WalkSpeed)) or "off" end)
        Diag:Feature("StealAnEgg.Waypoints", function() return tostring(#State.Waypoints) end)
        Diag:Watch("StealAnEgg voando", function() return State.Tween and "sim" or "nao" end)
        Diag:Command("sae", function()
            return "speed=" .. tostring(State.Toggles.Speed) ..
                " valor=" .. tostring(State.Values.WalkSpeed) ..
                " voo=" .. tostring(State.Tween ~= nil) ..
                " waypoints=" .. tostring(#State.Waypoints)
        end)
    end
end

env.SAE = State

return State

]],
    ["src/games/steal-an-exu.lua"] = [[
-- Steal An Exu - backend.
--
-- Esqueleto com uma feature: o Auto Steal Exu (src/games/features/stealanexu/
-- autosteal.lua). O backend sobe, carrega o modulo do repositorio, registra em
-- State.Features e monta a UI (categoria Farming, uma secao com o toggle e o
-- dropdown de Terreiro). A logica toda (teleporte, prompt, base) mora na feature.

local game, task, type, tostring, pcall = game, task, type, tostring, pcall
local Players = game:GetService("Players")

local LocalPlayer = Players.LocalPlayer
local env = type(getgenv) == "function" and getgenv() or _G
local STATE_KEY = "__DEPHUB_STEALANEXU"

-- Um reload limpo: derruba a sessao anterior antes de subir a nova.
local previous = env[STATE_KEY]
if type(previous) == "table" and type(previous.Destroy) == "function" then
    pcall(previous.Destroy, previous)
end

if not LocalPlayer then
    return false
end

local sourceBase = (env.__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"

-- Mesmo caminho de fetch do backend do Blox Fruits: o resolver do bundle quando
-- existe (build empacotado), senao game:HttpGet (checkout por fonte).
local function fetch(path)
    local cb = tostring((env.__DEPHUB or {}).SourceCacheBust or "")
    local url = sourceBase .. path .. (cb ~= "" and ("?cb=" .. cb) or "")
    local resolver = (type(env.__dephubHttpGet) == "function" and env.__dephubHttpGet)
        or (type(env.__DEPHUB_HTTP_GET) == "function" and env.__DEPHUB_HTTP_GET)
        or (type(_G.__dephubHttpGet) == "function" and _G.__dephubHttpGet)
        or (type(_G.__DEPHUB_HTTP_GET) == "function" and _G.__DEPHUB_HTTP_GET)
    if resolver then
        local ok, source = pcall(resolver, url)
        if ok and type(source) == "string" and #source > 0 then return true, source end
    end
    local ok, source = pcall(function() return __dephubHttpGet(url) end)
    if ok and type(source) == "string" and #source > 0 then return true, source end
    return false, tostring(source)
end

-- Carrega um modulo de feature do repositorio. Nao derruba o backend se falhar:
-- sem a feature, o painel sobe e o toggle reporta indisponivel.
local function loadFeature(relativePath, validate)
    local okFetch, source = fetch(relativePath)
    if not okFetch then return nil, "fetch: " .. tostring(source) end
    local chunk, compileError = loadstring(source)
    if type(chunk) ~= "function" then return nil, "compile: " .. tostring(compileError) end
    local okRun, module = pcall(chunk)
    if not okRun or type(module) ~= "table" or not validate(module) then return nil, "run: " .. tostring(module) end
    return module
end

local AutoStealModule, autoStealError = loadFeature("src/games/features/stealanexu/autosteal.lua", function(module)
    return type(module.new) == "function"
end)

local State = {
    Version = "0.1.1",
    Destroyed = false,
    Started = false,
    Features = {},
    LastError = nil,
}

env[STATE_KEY] = State
env.__DEPHUB = env.__DEPHUB or {}
env.__DEPHUB.StealAnExu = State

-- Liga/desliga uma feature pelo nome. So age sobre uma feature registrada em
-- State.Features: um nome desconhecido devolve false em vez de criar estado
-- fantasma ou erro. E o contrato que a UI usa.
function State:SetFeature(name, enabled)
    if self.Destroyed or type(name) ~= "string" then return false end
    local feature = self.Features[name]
    if type(feature) ~= "table" or type(feature.SetEnabled) ~= "function" then
        return false
    end
    local ok, result = pcall(feature.SetEnabled, feature, enabled == true)
    if not ok then
        self.LastError = tostring(result)
        return false
    end
    return result ~= false
end

function State:IsEnabled(name)
    if self.Destroyed or type(name) ~= "string" then return false end
    local feature = self.Features[name]
    if type(feature) ~= "table" then return false end
    if type(feature.IsEnabled) == "function" then return feature.IsEnabled(feature) == true end
    return feature.Enabled == true
end

function State:Start()
    if self.Started or self.Destroyed then return false end
    self.Started = true
    return true
end

function State:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true

    -- Derruba toda feature registrada (cada uma limpa o que ligou).
    for _, feature in pairs(self.Features) do
        if type(feature) == "table" and type(feature.Destroy) == "function" then
            pcall(feature.Destroy, feature)
        end
    end
    self.Features = {}

    if env[STATE_KEY] == self then
        env[STATE_KEY] = nil
    end
    if env.__DEPHUB and env.__DEPHUB.StealAnExu == self then
        env.__DEPHUB.StealAnExu = nil
    end
end

local AutoUpgradeModule, autoUpgradeError = loadFeature("src/games/features/stealanexu/autoupgrade.lua", function(module)
    return type(module.new) == "function"
end)

-- Contexto COMPARTILHADO das features: os helpers de mundo que as duas usam
-- (achar a MINHA base pelo Owner, e navegar um caminho dentro dela). Fica aqui,
-- num lugar so, pra nao duplicar a logica de Owner em cada feature.
local FeatureContext = {}
do
    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local LocalPlayer = Players.LocalPlayer

    -- A minha base: varre Map.Pens e compara o atributo Owner com o MEU UserId.
    -- Nunca Pen1/Pen2 fixo -- a numeracao muda por servidor -- e funciona pra
    -- quem receber o script, nao so pra mim.
    function FeatureContext.MyPen()
        local map = Workspace:FindFirstChild("Map")
        local pens = map and map:FindFirstChild("Pens")
        if not pens then return nil end
        local myUserId = LocalPlayer and LocalPlayer.UserId
        if not myUserId then return nil end
        local wanted = tostring(myUserId)
        for _, pen in ipairs(pens:GetChildren()) do
            local owner = pen:GetAttribute("Owner")
            if owner ~= nil and tostring(owner) == wanted then return pen end
        end
        return nil
    end

    -- Navega um caminho pontuado a partir da minha base (ex.:
    -- "PenSign.Board.ClickDetector"). Devolve a instancia, ou nil.
    function FeatureContext.PenPart(path)
        local instance = FeatureContext.MyPen()
        if not instance then return nil end
        for segment in tostring(path or ""):gmatch("[^.]+") do
            instance = instance:FindFirstChild(segment)
            if not instance then return nil end
        end
        return instance
    end
end

-- Instancia o Auto Steal Exu (mecanismo pronto; so roda quando o toggle ligar).
if AutoStealModule then
    State.AutoSteal = AutoStealModule.new(FeatureContext)
    State.Features.AutoSteal = State.AutoSteal
else
    warn("[DepHub] Steal An Exu autosteal unavailable: " .. tostring(autoStealError))
end

-- Auto Upgrade: duas instancias do MESMO mecanismo (o botao da base e o da
-- esteira sao o mesmo click), mudando so o caminho dentro do pen.
if AutoUpgradeModule then
    State.UpgradeBase = AutoUpgradeModule.new(FeatureContext, {
        label = "base", path = "PenSign.Board.ClickDetector",
    })
    State.UpgradeTread = AutoUpgradeModule.new(FeatureContext, {
        label = "tread", path = "TreadSign.Board.ClickDetector",
    })
    State.Features.UpgradeBase = State.UpgradeBase
    State.Features.UpgradeTread = State.UpgradeTread
else
    warn("[DepHub] Steal An Exu autoupgrade unavailable: " .. tostring(autoUpgradeError))
end

State:Start()

-- ---------------------------------------------------------------------------
-- Apresentacao: categoria Farming.
--   * "Auto Steal Exu" -- o loop (toggle). Varre TODOS os Exus do Runtime.
--     Guardar na base e o proprio teleporte de volta -- sem knob separado.
--   * "Steal All" -- um botao de passada unica: todos os Exus do Runtime, com
--     wait entre cada um.
-- ---------------------------------------------------------------------------
do
    local Kit = env.__DEPHUB and env.__DEPHUB.UIKit
    if Kit then
        local tab = Kit.Tab("Auto Steal", "Farming")

        local feature = State.AutoSteal
        if feature then
            local section = Kit.Section(tab, "Auto Steal Exu", "Left")
            if section then
                section:CreateToggle("Auto Steal Exu", false, function(value)
                    feature:SetEnabled(value)
                end)
            end
            local allSection = Kit.Section(tab, "Steal All", "Left")
            if allSection then
                allSection:CreateButton("Steal All", function()
                    feature:StartStealAll()
                end)
            end
        end

        -- Auto Upgrade: um toggle por botao (o da base e o da esteira).
        if State.UpgradeBase or State.UpgradeTread then
            local upgradeSection = Kit.Section(tab, "Auto Upgrade", "Left")
            if upgradeSection then
                if State.UpgradeBase then
                    upgradeSection:CreateToggle("Auto Upgrade Base", false, function(value)
                        State.UpgradeBase:SetEnabled(value)
                    end)
                end
                if State.UpgradeTread then
                    upgradeSection:CreateToggle("Auto Upgrade Esteira", false, function(value)
                        State.UpgradeTread:SetEnabled(value)
                    end)
                end
            end
        end
    end
end

return State

